files.hooks/register.tsx:
// mem-gauge: a memory gauge under the composer and a Memory pane that shows
// what is eating this Mac's RAM across Claude sessions, agents, models and
// other apps, with rule-based advice. Every session running the mod publishes
// a small heartbeat file under ~/.claude/mem-gauge/sessions/, so any one
// session's pane sees them all. Drawings read $.state only; processes run from
// the timer, a command or a press, never while drawing.
//
// The engine requires `$` to be handed only to functions declared at the top of
// this file, so every function that touches `$` lives here; the parsing and the
// advice rules are pure and live in parse.ts and advice.ts.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { DiskReport, SessionRow, Snapshot, WrapRequest } from '../types'
import { advise, applyHome, compactReport, diskActionArgv, diskActionLabel, diskActionQuestion, diskAdvice, quitAppArgv, summaryLine } from './advice'
import type { Advice, AdviceAction, AdviceOptions, DiskAdvice } from './advice'
import {
  bar,
  basename,
  buildMachine,
  claimUnregistered,
  cleanBranch,
  decodeEngineSession,
  decodeMachine,
  diskLine,
  engineRow,
  decodeWrapRequest,
  descendants,
  encodeMachine,
  footerParts,
  formatBytes,
  glyph,
  formatMB,
  isCollectable,
  isEngineName,
  isSessionId,
  parseDfAll,
  parseDu,
  oneLine,
  parseEntry,
  parsePs,
  ringSvg,
  rowOf,
  shortModel,
  sortRows,
  statusLine,
  summaryParts,
  statusOf,
  topApps,
  treeMB,
} from './parse'
import type { MachineFile, Proc, RegistryEntry } from './parse'

type Dollar = EngineInterface

// $.state values, one literal plugin/key reference each, so `claude plugin
// validate` holds them to types/index.d.ts. Written only from handlers, timers
// and events, never while drawing.
const snapshotRef = atom({ plugin: 'mem-gauge', key: 'snapshot' } as const, null)
const enginePidRef = atom({ plugin: 'mem-gauge', key: 'enginePid' } as const, null)
const pidCheckedRef = atom({ plugin: 'mem-gauge', key: 'pidChecked' } as const, false)
const lastActivityRef = atom({ plugin: 'mem-gauge', key: 'lastActivityAt' } as const, 0)
const askedRef = atom({ plugin: 'mem-gauge', key: 'asked' } as const, {})
const labelRef = atom({ plugin: 'mem-gauge', key: 'label' } as const, null)
const figuresRef = atom({ plugin: 'mem-gauge', key: 'figures' } as const, null)
const wrapRef = atom({ plugin: 'mem-gauge', key: 'wrapRequest' } as const, null)
const showAllRef = atom({ plugin: 'mem-gauge', key: 'showAllSessions' } as const, false)
const diskRef = atom({ plugin: 'mem-gauge', key: 'disk' } as const, null)
const applyingRef = atom({ plugin: 'mem-gauge', key: 'applying' } as const, [] as string[])

const PANE = 'mem-gauge'
const DISK_PANE = 'mem-gauge-disk'
/** The disk pane re-reads the volumes and folders when its report is older than this. */
const DISK_REFRESH_AFTER_MS = 60_000
/** The folders that usually eat a Mac developer's disk, measured with `du -sk` when the disk pane opens. */
const DISK_FOLDERS: readonly { rel: string; label: string }[] = [
  { rel: '.claude/projects', label: 'Claude transcripts (~/.claude/projects)' },
  { rel: '.claude/file-history', label: 'Claude file history' },
  { rel: 'Library/Developer/Xcode/DerivedData', label: 'Xcode DerivedData' },
  { rel: 'Library/Developer/CoreSimulator/Devices', label: 'iOS simulator devices' },
  { rel: 'Library/Caches', label: 'Library caches' },
  { rel: '.Trash', label: 'Trash' },
]
const ASK = 'Ask to wrap'
const APPLY = 'Apply'
const COMPACT = 'Compact'
const HAND_OFF = 'Hand off'
/** An Apply's command (a find over a big folder, simctl) may take a while. */
const APPLY_TIMEOUT_MS = 120_000
/** An app asked to quit may first show a save sheet; the request is delivered either way. */
const QUIT_TIMEOUT_MS = 30_000
/** The disk icon on surfaces with no vector element: stacked discs (U+26C1). */
const DISK_GLYPH = '\u26C1'
/** The pane lists this many active sessions, biggest first, until View all is pressed. */
const TOP_SESSIONS = 10
const ASK_EVERY_MS = 10 * 60_000
/** /mem and a press of the gauge re-read when the snapshot is older than this. */
const REFRESH_AFTER_MS = 10_000
const TIMEOUT_MS = 5000
/** du over a big folder (the simulator devices run past 5 s on a full Mac); the pane says it is reading meanwhile. */
const DU_TIMEOUT_MS = 10_000
/** A shared machine reading younger than this (plus jitter) is reused, not re-collected. */
const FRESH_MS = 25_000
const JITTER_MS = 5000
/** A wrap request older than this is dropped unseen. */
const WRAP_TTL_MS = 30 * 60_000
const MAX_FILES = 200
const MAX_GC_PER_TICK = 10
/** Engine session records read per tick for sessions that do not run the mod. */
const MAX_ENGINE_ROWS = 60
const ACTIVE_AGENT = new Set(['pending', 'running', 'waiting'])
/** A request stamped further ahead than this is refused: a future `at` would never expire. */
const CLOCK_SKEW_MS = 60_000
/**
 * The origins that count as the person: their own Enter, the Remote Control
 * bridge, and the SDK host (the desktop Code tab drives the engine through
 * it). Only these open (and focus) the pane. Every other origin, and any kind
 * this list does not know, gets one summary line in a session that draws (no
 * other session's label lands in this transcript on a peer's or a schedule's
 * say-so), and the table only where nothing can draw (-p).
 */
const PANE_ORIGINS = new Set(['composer', 'bridge', 'sdk'])
/**
 * Inconclusive pid probes (sh or ps failed or timed out) retried before giving
 * up; a clear answer (an engine, or ps naming something else) is cached at once.
 */
const MAX_PID_PROBES = 5
/** sysctl names read on every collection; memory size and cores never change, so they are read once. */
const DYNAMIC_SYSCTL = ['kern.memorystatus_level', 'vm.swapusage', 'vm.loadavg']

type TickResult = { snapshot: Snapshot; wrap: WrapRequest | null; newRequest: WrapRequest | null }

// Per-load plumbing, not state: register() sets the options, and a hot reload
// starts these over together with the timers it cancels; session.start (or the
// next turn) arms again.
let config = { intervalMs: 30_000, advice: { idleMinutes: 30, contextTokens: 150_000 } as AdviceOptions, showStatus: true, footerButtons: true, footerCompact: false }
let timer: { cancel: () => void } | null = null
let running: Promise<TickResult | null> | null = null
let diskScan: Promise<void> | null = null
// True while a main-loop turn runs (turn.start to turn.complete): a hand-off then waits, so
// the note is written over the whole turn and /clear does not cut it short.
let turnInFlight = false
// Apply presses in flight, by tip key, each under a token so only the press that claimed releases
// (a reload resets the map; a claim from before it can no longer clear a new one). Mirrored to $.state for drawing.
let applying = new Map<string, number>()
let applyToken = 0
let dirCache: string | null = null
let hardware: { totalBytes: number; cores: number } | null = null
// Inconclusive pid probes this load; a hot reload allows a few more, which is harmless.
let pidProbes = 0

const clamp = (value: unknown, fallback: number, min: number, max: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback

/** An error's kind only: a message could carry a path or command output. */
const kindOf = (err: unknown): string => (err instanceof Error && err.name ? err.name : 'error')

/** `HOME` from the environment, as an absolute path; never '~'. */
async function dataDir($: Dollar): Promise<string | null> {
  if (dirCache) return dirCache
  try {
    const home = await $.env.get('HOME')
    dirCache = home && home.startsWith('/') ? `${home.replace(/\/+$/, '')}/.claude/mem-gauge` : null
  } catch {
    dirCache = null
  }
  return dirCache
}

/** stdout of one argv, or null when it failed to start, timed out, or said nothing. */
async function runText($: Dollar, argv: string[], cwd: string | undefined, timeoutMs = TIMEOUT_MS): Promise<string | null> {
  try {
    const r = await $.process.run(argv, { cwd, timeoutMs })
    return r.stdout.trim() === '' ? null : r.stdout
  } catch {
    return null
  }
}

async function readText($: Dollar, path: string): Promise<string | null> {
  try {
    const text = await $.fs.read(path)
    return typeof text === 'string' ? text : null
  } catch {
    return null
  }
}

async function writeText($: Dollar, path: string, text: string): Promise<boolean> {
  try {
    await $.fs.write(path, text)
    return true
  } catch {
    return false
  }
}

/** Removes one of mem-gauge's own files ($.fs has no remove). */
async function removeFile($: Dollar, path: string): Promise<void> {
  try {
    await $.process.run(['rm', '-f', path], { timeoutMs: TIMEOUT_MS })
  } catch {
    // A file left behind is collected by a later tick.
  }
}

/** One sysctl for every name, vm_stat, df and ps, in parallel. */
async function collectMachine($: Dollar, now: number, cwd: string | undefined): Promise<MachineFile> {
  const known = hardware
  const [sysctl, vmStat, df, ps] = await Promise.all([
    runText($, ['sysctl', ...(known ? [] : ['hw.memsize', 'hw.ncpu']), ...DYNAMIC_SYSCTL], cwd),
    runText($, ['vm_stat'], cwd),
    runText($, ['df', '-k', '/'], cwd),
    runText($, ['ps', '-axo', 'pid=,ppid=,rss=,comm='], cwd),
  ])
  const procs = ps === null ? [] : parsePs(ps)
  // The cached constants are handed to the same parser as sysctl's own lines.
  const constants = known ? `hw.memsize: ${known.totalBytes}\nhw.ncpu: ${known.cores}\n` : ''
  const stats = buildMachine(now, { sysctl: constants + (sysctl ?? '') || null, vmStat, df })
  if (!known && stats.totalBytes !== null && stats.cores !== null) hardware = { totalBytes: stats.totalBytes, cores: stats.cores }
  return { v: 1, at: now, stats, procs: procs.length > 0 ? procs : null }
}

/**
 * The shared reading when another session took it recently; otherwise this
 * session collects and shares it. Two sessions collecting at once is the only
 * race, and it is harmless, so there is no lock.
 */
async function machineReading($: Dollar, dir: string | null, now: number, cwd: string | undefined): Promise<MachineFile> {
  if (dir) {
    const text = await readText($, `${dir}/machine.json`)
    const shared = text === null ? null : decodeMachine(text)
    if (shared && shared.at <= now && now - shared.at < FRESH_MS + Math.random() * JITTER_MS) return shared
  }
  const fresh = await collectMachine($, now, cwd)
  if (dir) await writeText($, `${dir}/machine.json`, encodeMachine(fresh))
  return fresh
}

/**
 * The engine's pid: the parent of a `sh` this plugin starts, accepted only when
 * ps names it claude/node/bun. There is no pid API, so an unverified answer
 * stays null and the pane says "unknown" rather than show a wrong number.
 */
async function enginePid($: Dollar, cwd: string | undefined): Promise<number | null> {
  if (await read($, pidCheckedRef)) return read($, enginePidRef)
  // A clear answer is cached for the session; anything else (a failed or
  // timed-out sh or ps, an empty answer) is retried on later ticks, so one
  // transient failure does not leave "this session unknown" for good.
  let answer: { pid: number | null } | null = null
  try {
    const echoed = await $.process.run(['sh', '-c', 'echo $PPID'], { cwd, timeoutMs: TIMEOUT_MS })
    const candidate = Number(echoed.stdout.trim())
    if (echoed.exitCode === 0 && Number.isSafeInteger(candidate) && candidate > 1) {
      const comm = await $.process.run(['ps', '-o', 'comm=', '-p', String(candidate)], { cwd, timeoutMs: TIMEOUT_MS })
      const name = basename(comm.stdout.trim())
      if (comm.exitCode === 0 && name !== '') answer = { pid: isEngineName(name) ? candidate : null }
    }
  } catch {
    // Could not start or timed out: inconclusive.
  }
  if (!answer) {
    pidProbes += 1
    if (pidProbes < MAX_PID_PROBES) return null
    answer = { pid: null }
  }
  const pid = answer.pid
  await update($, enginePidRef, () => pid)
  await update($, pidCheckedRef, () => true)
  return pid
}

/** "<repo basename> · <branch>" from the session's root and its cwd's checked-out branch. */
async function refreshLabel($: Dollar): Promise<void> {
  try {
    const root = await $.session.root()
    const cwd = await $.session.cwd()
    const out = await runText($, ['git', 'rev-parse', '--abbrev-ref', 'HEAD'], cwd)
    const branch = out === null ? null : cleanBranch(out)
    const name = oneLine(basename(root), 100) || 'session'
    await update($, labelRef, () => (branch ? `${name} · ${branch}` : name))
  } catch {
    // The label falls back to the cwd's basename.
  }
}

/** This session's registry entry: figures only, never prompt text or a secret. */
async function ownEntry($: Dollar, sessionId: string, pid: number | null, rssMB: number | null, cwd: string, now: number): Promise<RegistryEntry> {
  const [usage, model, agents] = await Promise.all([
    $.session.usage().catch(() => null),
    $.session.model().catch(() => ''),
    $.agent.list().catch(() => []),
  ])
  const label = await read($, labelRef)
  const lastActivityAt = await read($, lastActivityRef)
  const figures = await read($, figuresRef)
  const rateLimit = usage && usage.rateLimits.length > 0 ? Math.max(...usage.rateLimits.map(r => r.percentUsed)) : null
  const startedAt = usage?.startedAt ?? now
  return {
    v: 1,
    sessionId,
    pid,
    label: label ?? (oneLine(basename(cwd), 100) || 'session'),
    cwd,
    model,
    rssMB,
    contextPercent: usage?.context.percent ?? figures?.contextPercent ?? null,
    contextTokens: usage?.context.tokens ?? figures?.contextTokens ?? null,
    contextWindow: usage?.context.window ?? figures?.contextWindow ?? null,
    rateLimitPercent: rateLimit ?? figures?.rateLimitPercent ?? null,
    // list() keeps finished agents until the engine drops them.
    agents: agents.filter(a => ACTIVE_AGENT.has(a.status)).length,
    // Before any turn the session has been idle since it started.
    lastActivityAt: Math.max(lastActivityAt, startedAt),
    startedAt,
    updatedAt: now,
  }
}

type RegistryFile = { path: string; entry: RegistryEntry | null; mtimeMs: number }

/** Every other session's entry; an unreadable file is kept as null for garbage collection. */
async function readRegistry($: Dollar, dir: string, thisId: string): Promise<RegistryFile[]> {
  let list: { name: string; kind: string; mtimeMs: number }[] = []
  try {
    list = await $.fs.list(`${dir}/sessions`)
  } catch {
    return [] // no folder yet
  }
  const files = list
    .filter(f => f.kind === 'file' && f.name.endsWith('.json') && isSessionId(f.name.slice(0, -5)) && f.name !== `${thisId}.json`)
    .slice(0, MAX_FILES)
  const texts = await Promise.all(files.map(f => readText($, `${dir}/sessions/${f.name}`)))
  return files.map((f, i) => {
    const text = texts[i] ?? null
    const entry = text === null ? null : parseEntry(text)
    // A file whose content names another id is treated as unreadable.
    return { path: `${dir}/sessions/${f.name}`, entry: entry && `${entry.sessionId}.json` === f.name ? entry : null, mtimeMs: f.mtimeMs }
  })
}

/** Picks up (and removes) a wrap request another session left for this one. */
async function takeWrapRequest($: Dollar, dir: string, sessionId: string, now: number): Promise<WrapRequest | null> {
  const path = `${dir}/requests/${sessionId}.json`
  const text = await readText($, path)
  if (text === null) return null
  await removeFile($, path)
  const request = decodeWrapRequest(text)
  return request && isCurrent(request, now) ? request : null
}

/** A wrap request still worth showing: not expired, and not stamped in the future. */
const isCurrent = (request: WrapRequest, now: number): boolean =>
  request.at <= now + CLOCK_SKEW_MS && now - request.at < WRAP_TTL_MS

/**
 * Removes request files nobody picked up (the target crashed or never ran
 * mem-gauge), so the folder does not grow. Only session-id-named files are
 * touched; the cap keeps one tick's work bounded.
 */
async function collectRequests($: Dollar, dir: string, now: number): Promise<void> {
  let list: { name: string; kind: string; mtimeMs: number }[] = []
  try {
    list = await $.fs.list(`${dir}/requests`)
  } catch {
    return // no folder yet
  }
  const old = list
    .filter(f => f.kind === 'file' && f.name.endsWith('.json') && isSessionId(f.name.slice(0, -5)) && now - f.mtimeMs > WRAP_TTL_MS)
    .slice(0, MAX_GC_PER_TICK)
  for (const f of old) await removeFile($, `${dir}/requests/${f.name}`)
}

/** One full tick; runTick keeps two from overlapping. */
async function tick($: Dollar): Promise<TickResult> {
  const now = await $.clock.now()
  // Re-read every tick: /clear moves the process to a new id with no session.start.
  const sessionId = await $.session.id()
  const cwd = await $.session.cwd().catch(() => '')
  const runCwd = cwd || undefined
  const dir = await dataDir($)

  const [machine, pid] = await Promise.all([machineReading($, dir, now, runCwd), enginePid($, runCwd)])
  const procs: Proc[] = machine.procs ?? []
  const thisMB = pid === null ? null : treeMB(procs, pid)

  const own = await ownEntry($, sessionId, pid, thisMB, cwd, now)
  // After /clear the old id's heartbeat would read as a second live session on
  // the same pid. session.end removes it, but that hook can lose its 1.5 s
  // bound, so the first tick under the new id removes it too.
  const previous = (await read($, snapshotRef))?.sessionId
  const clearedId = previous && previous !== sessionId && isSessionId(previous) ? previous : null
  if (dir && clearedId) await removeFile($, `${dir}/sessions/${clearedId}.json`)
  const registry = dir ? await readRegistry($, dir, sessionId) : []
  const others = registry.filter(f => !clearedId || !f.path.endsWith(`/${clearedId}.json`))
  if (dir && isSessionId(sessionId)) await writeText($, `${dir}/sessions/${sessionId}.json`, JSON.stringify(own))

  const index = machine.procs ? { at: machine.at, byPid: new Map(procs.map(p => [p.pid, p])) } : null
  const rows = [rowOf(own, 'live', now, sessionId)]
  const claude = new Set<number>(pid === null ? [] : descendants(procs, pid))
  let collected = 0
  for (const { path, entry, mtimeMs } of others) {
    const status = entry ? statusOf(entry, now, index) : null
    if (collected < MAX_GC_PER_TICK && isCollectable(entry, status, now, mtimeMs)) {
      collected += 1
      await removeFile($, path)
      continue
    }
    if (!entry || !status) continue
    rows.push(rowOf(entry, status, now, sessionId))
    if (status !== 'gone' && entry.pid !== null) for (const p of descendants(procs, entry.pid)) claude.add(p)
  }

  // Several sessions asking at once (or one asking again) overwrite one file and
  // raise one toast: while a request is already showing, a new one only
  // refreshes it.
  const before = await read($, wrapRef)
  const wasShowing = before !== null && isCurrent(before, now)
  const taken = dir && isSessionId(sessionId) ? await takeWrapRequest($, dir, sessionId, now) : null
  if (taken) await update($, wrapRef, () => taken)
  // Derived, not re-read: every read of one dispatch may see the moment it
  // began, so a read here could miss the write above (and then clear it).
  const held = taken ?? before
  const wrap = held && isCurrent(held, now) ? held : null
  if (!taken && before && !wrap) await update($, wrapRef, () => null)
  const newRequest = taken && !wasShowing ? taken : null
  if (dir) await collectRequests($, dir, now)

  // Claims the unregistered engines' trees too, so neither they nor their MCP
  // servers are listed as "other apps". Each one with a session record of the
  // engine's own (~/.claude/sessions/<pid>.json) is listed by name with its
  // memory; the rest are summed on one line.
  const claimed = machine.procs ? claimUnregistered(procs, claude) : null
  let unregistered: { count: number; rssMB: number } | null = null
  if (claimed) {
    unregistered = { count: 0, rssMB: 0 }
    const home = await homeDir($)
    const listed = new Set(rows.map(r => r.sessionId))
    for (const root of claimed.roots.slice(0, MAX_ENGINE_ROWS)) {
      const text = home ? await readText($, `${home}/.claude/sessions/${root.pid}.json`) : null
      const session = text ? decodeEngineSession(text, root.pid, now) : null
      if (session && !listed.has(session.sessionId)) {
        listed.add(session.sessionId)
        rows.push(engineRow(root.pid, root.rssMB, session))
      } else {
        unregistered.count += 1
        unregistered.rssMB += root.rssMB
      }
    }
    for (const root of claimed.roots.slice(MAX_ENGINE_ROWS)) {
      unregistered.count += 1
      unregistered.rssMB += root.rssMB
    }
  }
  const snapshot: Snapshot = {
    at: now,
    sessionId,
    machine: machine.stats,
    thisSessionMB: thisMB,
    sessions: sortRows(rows).slice(0, 60),
    unregistered,
    topApps: topApps(procs, claude, 10),
  }
  await update($, snapshotRef, () => snapshot)
  return { snapshot, wrap, newRequest }
}

function publishStatus($: Dollar, snapshot: Snapshot, wrap: WrapRequest | null): void {
  // Never clear with `undefined`: on the desktop host that call stops every
  // later render from reaching this plugin (seen on app 2.31226 / CLI 2.1.293),
  // so a line pinned by an earlier load stays until the session restarts.
  if (config.showStatus) $.ui.status(statusLine(snapshot, wrap))
}

/** One tick at a time: a tick that outlasts the period, or a /mem during one, joins it. */
function runTick($: Dollar): Promise<TickResult | null> {
  if (running) return running
  let mine: Promise<TickResult | null> | null = null
  mine = (async () => {
    try {
      const result = await tick($)
      if (result.newRequest) {
        const frees = result.newRequest.freesMB === null ? '' : ` (frees about ${formatMB(result.newRequest.freesMB)})`
        $.ui.toast(`Memory: another session asked this one to wrap up${frees}. Nothing runs on its own.`, { timeoutMs: 10_000 })
      }
      publishStatus($, result.snapshot, result.wrap)
      return result
    } catch (err) {
      $.ui.log(`mem-gauge: tick failed (${kindOf(err)})`, { to: 'debug' })
      return null
    } finally {
      // Only the tick that holds the slot clears it (a hot reload resets the slot under a running tick).
      if (running === mine) running = null
    }
  })()
  running = mine
  return mine
}

function arm($: Dollar): void {
  if (timer) return
  timer = $.clock.every(config.intervalMs, () => {
    void runTick($)
  })
}

async function markActive($: Dollar): Promise<void> {
  const now = await $.clock.now()
  await update($, lastActivityRef, () => now)
}

/** Opens the pane: from /mem or a press of the gauge, so it is placed at any width. */
async function openPane($: Dollar) {
  const wrap = await read($, wrapRef)
  const opened = await $.ui.open({ id: PANE, title: 'Memory', focus: true, closeOnEscape: true })
  // Only a placed pane counts as seen: an unplaced one keeps the reminder.
  if (wrap && opened.isPlaced) {
    await update($, wrapRef, () => null)
    const shown = await read($, snapshotRef)
    if (shown) publishStatus($, shown, null)
  }
  const snapshot = await read($, snapshotRef)
  if (!snapshot || (await $.clock.now()) - snapshot.at > REFRESH_AFTER_MS) void runTick($)
  return opened
}

/** `HOME`, derived from the data dir (which is `$HOME/.claude/mem-gauge`). */
async function homeDir($: Dollar): Promise<string | null> {
  const dir = await dataDir($)
  return dir ? dir.replace(/\/\.claude\/mem-gauge$/, '') : null
}

/** Reads every volume (`df -kP`, 5 s) and the usual big folders (`du -sk` each, in parallel, 10 s each) into the disk report. */
async function diskReading($: Dollar): Promise<void> {
  const now = await $.clock.now()
  const cwd = (await $.session.cwd().catch(() => '')) || undefined
  const home = await homeDir($)
  const paths = DISK_FOLDERS.map(f => (home ? `${home}/${f.rel}` : null))
  const [df, ...dus] = await Promise.all([
    runText($, ['df', '-kP'], cwd),
    ...paths.map(path => (path ? runText($, ['du', '-sk', path], cwd, DU_TIMEOUT_MS) : Promise.resolve(null))),
  ])
  const report: DiskReport = {
    at: now,
    volumes: df ? parseDfAll(df) : [],
    folders: DISK_FOLDERS.map((f, i) => ({ path: paths[i] ?? f.rel, label: f.label, bytes: dus[i] ? parseDu(dus[i]) : null })),
  }
  await update($, diskRef, () => report)
}

/** One disk reading at a time: a Refresh during one joins it; `fresh` waits for it and then reads again (after an Apply). */
async function runDiskScan($: Dollar, fresh = false): Promise<void> {
  if (diskScan) {
    if (!fresh) return diskScan
    await diskScan.catch(() => undefined)
  }
  let mine: Promise<void> | null = null
  mine = diskReading($)
    .catch(err => {
      $.ui.log(`mem-gauge: disk reading failed (${kindOf(err)})`, { to: 'debug' })
    })
    .finally(() => {
      // Only the scan that holds the slot clears it: a hot reload resets the slot under a running scan.
      if (diskScan === mine) diskScan = null
    })
  diskScan = mine
  return mine
}

async function openDiskPane($: Dollar) {
  const opened = await $.ui.open({ id: DISK_PANE, title: 'Disk', focus: true, closeOnEscape: true })
  const now = await $.clock.now()
  const report = await read($, diskRef)
  if (!report || now - report.at > DISK_REFRESH_AFTER_MS) void runDiskScan($)
  const snapshot = await read($, snapshotRef)
  if (!snapshot || now - snapshot.at > REFRESH_AFTER_MS) void runTick($)
  return opened
}

/**
 * Claims a tip's Apply from the press until it is over (dialog included): a
 * second press meanwhile is ignored. The module set is the truth (a reload
 * resets it); $.state mirrors it so the pane draws Applying.
 */
async function beginApply($: Dollar, key: string): Promise<number | null> {
  if (applying.has(key)) return null
  const token = ++applyToken
  applying.set(key, token)
  try {
    await update($, applyingRef, held => (held.includes(key) ? held : [...held, key]))
  } catch (err) {
    // The claim is only as good as its mirror: a press that cannot draw Applying is let go.
    if (applying.get(key) === token) applying.delete(key)
    $.ui.log(`mem-gauge: apply state (${kindOf(err)})`, { to: 'debug' })
    return null
  }
  return token
}

async function endApply($: Dollar, key: string, token: number): Promise<void> {
  if (applying.get(key) !== token) return
  applying.delete(key)
  await update($, applyingRef, held => held.filter(k => k !== key)).catch(() => undefined)
}

/**
 * Apply on a Disk tip: confirms in the engine's own dialog, then runs the
 * one fixed command for that action (argv, no shell, paths from $HOME and a
 * fixed list) with a long timeout, says how it went, and re-reads the sizes.
 * A press while it runs, a dismissed dialog, or Cancel does nothing.
 */
async function applyDisk($: Dollar, tip: DiskAdvice): Promise<void> {
  if (!tip.action) return
  const key = `disk:${tip.key}`
  const token = await beginApply($, key)
  if (token === null) return
  let ran = false
  try {
    let choice: string
    try {
      choice = await $.ui.ask(diskActionQuestion(tip.action), { options: [APPLY, 'Cancel'], header: 'Disk' })
    } catch {
      return
    }
    if (choice !== APPLY) return
    const home = applyHome(await homeDir($))
    if (!home) {
      $.ui.toast('Disk: cannot apply, HOME is unknown or not a plain absolute path.')
      return
    }
    const label = diskActionLabel(tip.action)
    try {
      const r = await $.process.run(diskActionArgv(tip.action, home), { timeoutMs: APPLY_TIMEOUT_MS })
      ran = true
      $.ui.toast(
        r.exitCode === 0
          ? `Disk: done, ${label}. Re-reading sizes.`
          : `Disk: ${label} finished with errors (exit ${r.exitCode}); some entries may be protected. Re-reading sizes.`,
      )
    } catch (err) {
      // A timeout may have removed part of the folder: re-read either way.
      ran = true
      $.ui.toast(`Disk: could not finish ${label} (${kindOf(err)}); some entries may be gone. Re-reading sizes.`)
    }
  } finally {
    await endApply($, key, token)
  }
  if (ran) void runDiskScan($, true)
}

/** A Memory tip button's label, by what it does: the context tip names its two ways out, every other kind reads Apply. */
const actionLabel = (action: AdviceAction): string => (action.kind === 'compact' ? 'Compact' : action.kind === 'hand-off' ? HAND_OFF : APPLY)

/**
 * A press on a Memory tip's button (`action`, the tip's own by default; the
 * Hand off button passes `tip.secondary`): Ask to wrap (the existing flow, with
 * its own confirmation), compact this session, run /handoff (the handoff mod),
 * quit an app gracefully (confirmed), or open the Disk pane. A tip with no
 * action has no button.
 */
async function applyMemory($: Dollar, tip: Advice, rowsById: ReadonlyMap<string, SessionRow>, action = tip.action): Promise<void> {
  if (!action) return
  if (action.kind === 'ask-wrap') {
    const target = rowsById.get(action.sessionId)
    if (target) await askToWrap($, target)
    return
  }
  if (action.kind === 'open-disk') {
    await openDiskPane($)
    return
  }
  if (action.kind === 'hand-off') {
    await runHandoff($, tip)
    return
  }
  // A compact queued behind a hand-off's /clear (or the reverse) would act on the wrong conversation: one at a time per tip.
  if (applying.has(`handoff:${tip.key}`)) return
  const key = `memory:${tip.key}`
  const token = await beginApply($, key)
  if (token === null) return
  try {
    if (action.kind === 'compact') {
      let choice: string
      try {
        choice = await $.ui.ask('Compact this session now (the conversation so far is summarized to free context)?', { options: [COMPACT, 'Cancel'], header: 'Memory' })
      } catch {
        return
      }
      if (choice !== COMPACT) return
      try {
        await $.command.run({ command: 'compact' })
        $.ui.toast('Memory: /compact queued; it runs when the session is idle.')
      } catch (err) {
        $.ui.toast(`Memory: could not run /compact (${kindOf(err)}).`)
      }
      return
    }
    // quit-app
    const argv = quitAppArgv(action.app)
    if (!argv) {
      $.ui.toast('Memory: that app name cannot be passed to osascript safely; quit it yourself.')
      return
    }
    let choice: string
    try {
      choice = await $.ui.ask(`Quit ${action.app} the normal way (it may ask you to save first)?`, { options: [APPLY, 'Cancel'], header: 'Memory' })
    } catch {
      return
    }
    if (choice !== APPLY) return
    try {
      const r = await $.process.run(argv, { timeoutMs: QUIT_TIMEOUT_MS })
      $.ui.toast(r.exitCode === 0 ? `Memory: ${action.app} was asked to quit.` : `Memory: ${action.app} did not take the quit (exit ${r.exitCode}).`)
    } catch (err) {
      $.ui.toast(
        kindOf(err) === 'TimeoutError'
          ? `Memory: ${action.app} was asked to quit; it may be waiting on a save dialog.`
          : `Memory: could not ask ${action.app} to quit (${kindOf(err)}).`,
      )
    }
    void runTick($)
  } finally {
    await endApply($, key, token)
  }
}

/** What the Hand off button says when /handoff is refused: the mod that owns the flow is not installed. */
const HANDOFF_MISSING = 'Memory: the Hand off button needs the handoff mod (claude plugin install handoff@joseph-mods --scope user).'

/**
 * The Hand off button: runs `/handoff`, the handoff mod's command, which owns
 * the whole flow (its own dialog, the note, `/clear`, the pre-filled prompt).
 * This mod writes no note and makes no model call; it only decides when the
 * button may fire.
 *
 * Two guards stay here because only this mod sees the button: mid-turn the
 * press is refused with a toast (the handoff mod refuses too, but its answer
 * lands in the transcript, away from the pane that was pressed), and a claim
 * under `handoff:<key>` is held for the length of the `$.command.run` promise,
 * so a double press runs the command once and this tip's Compact waits
 * meanwhile. Re-entry past that (a second /handoff while its dialog is open)
 * is the handoff mod's own guard. A rejection (the engine refuses a name no
 * plugin registered) is read as the mod being absent, and the toast names its
 * install line.
 */
async function runHandoff($: Dollar, tip: Advice): Promise<void> {
  // A hand-off while this tip's compact is in flight would clear what the compact is about to summarize.
  if (applying.has(`memory:${tip.key}`)) return
  // Mid-turn, the note would miss the turn's work and /clear would cut it off: wait for the end.
  if (turnInFlight) {
    $.ui.toast('Memory: a turn is running; hand off once it has finished, so the note covers it.')
    return
  }
  const key = `handoff:${tip.key}`
  const token = await beginApply($, key)
  if (token === null) return
  try {
    await $.command.run({ command: 'handoff' })
  } catch {
    $.ui.toast(HANDOFF_MISSING)
  } finally {
    await endApply($, key, token)
  }
}

/**
 * Leaves a request file for another session's copy of this mod, which shows
 * its person a toast and a marker. No model reads it and nothing runs on its
 * own: a peer message would wake that session into a turn (spending the very
 * memory this frees) and could be read as an instruction to ship.
 */
async function askToWrap($: Dollar, row: SessionRow): Promise<void> {
  const now = await $.clock.now()
  const asked = await read($, askedRef)
  if (now - (asked[row.sessionId] ?? 0) < ASK_EVERY_MS) {
    $.ui.toast('Memory: that session was asked less than 10 minutes ago.')
    return
  }
  let choice: string
  try {
    choice = await $.ui.ask(
      `It has been idle ${row.idleMinutes ?? '?'} min and holds ${formatMB(row.rssMB)}. Ask "${row.label}" to wrap up?`,
      { options: [ASK, 'Cancel'], header: 'Memory' },
    )
  } catch {
    return // dismissed, or nobody to ask
  }
  if (choice !== ASK) return
  const dir = await dataDir($)
  const from = await $.session.id().catch(() => '')
  const isSent =
    dir !== null &&
    isSessionId(row.sessionId) &&
    isSessionId(from) &&
    (await writeText($, `${dir}/requests/${row.sessionId}.json`, JSON.stringify({ from, at: now, freesMB: row.rssMB })))
  if (!isSent) {
    $.ui.toast('Memory: could not leave the request (the mem-gauge folder is not writable).')
    return
  }
  await update($, askedRef, map => {
    const kept: Record<string, number> = {}
    for (const [id, at] of Object.entries(map ?? {})) if (now - at < ASK_EVERY_MS) kept[id] = at
    kept[row.sessionId] = now
    return kept
  })
  $.ui.toast(`Memory: asked "${row.label}" to wrap up. It sees a notice; nothing runs on its own.`)
}

export const register: Register = (on, options) => {
  config = {
    intervalMs: clamp(options['intervalSeconds'], 30, 10, 600) * 1000,
    advice: {
      idleMinutes: clamp(options['idleMinutes'], 30, 1, 24 * 60),
      // 0 is a real choice (the percent-of-window rule), so it is kept rather than clamped up to the minimum.
      contextTokens: options['contextTipTokens'] === 0 ? 0 : clamp(options['contextTipTokens'], 150_000, 20_000, 1_000_000),
    },
    showStatus: options['statusLine'] === true,
    footerButtons: options['footerButtons'] !== false,
    // One chip for both figures: the desktop's footer strip clips past two or three chips (option footerCompact).
    footerCompact: options['footerCompact'] === true,
  }
  timer = null
  running = null
  diskScan = null
  applying = new Map()
  dirCache = null
  hardware = null
  pidProbes = 0

  on('session.start', async ($, e, next) => {
    try {
      await $.command.register({
        name: 'mem',
        description: "Show what is using this Mac's memory across Claude sessions, agents and apps",
        immediate: true,
      })
    } catch (err) {
      $.ui.log(`mem-gauge: /mem not registered (${kindOf(err)})`, { to: 'debug' })
    }
    try {
      await $.command.register({
        name: 'disk',
        description: "Show this Mac's disk: the volume's use, every mounted volume, the usual big folders",
        immediate: true,
      })
    } catch (err) {
      $.ui.log(`mem-gauge: /disk not registered (${kindOf(err)})`, { to: 'debug' })
    }
    arm($)
    // A load starts with no Apply in flight: a reload mid-Apply must not leave a button at Applying.
    await update($, applyingRef, () => []).catch(() => undefined)
    // The first reading runs once the start has settled, never holding up the first prompt.
    $.clock.after(0, () => {
      void refreshLabel($).then(() => runTick($))
    })
    return next(e)
  })

  // Activity marks the session busy; turn.start fires for the main loop only.
  // Its prompt text is never read.
  on('turn.start', async ($, e, next) => {
    turnInFlight = true
    let result: Awaited<ReturnType<typeof next>>
    try {
      result = await next(e)
    } catch (err) {
      // A chain beneath that rejects may never see its turn.complete: do not leave the flag set.
      turnInFlight = false
      throw err
    }
    try {
      await markActive($)
      arm($)
    } catch {
      // Observing only.
    }
    return result
  })

  // The flag is cleared in a finally: a hook beneath that fails rejects next(e),
  // and a stuck flag would refuse every hand-off until a reload.
  on('turn.complete', async ($, e, next) => {
    let result: Awaited<ReturnType<typeof next>>
    try {
      result = await next(e)
    } finally {
      if (e.agentId === undefined) turnInFlight = false
    }
    if (e.agentId === undefined) {
      try {
        await markActive($)
        arm($)
        // The branch may have changed during the turn; git runs off the turn's path.
        $.clock.after(0, () => {
          void refreshLabel($)
        })
      } catch {
        // Observing only.
      }
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    const result = await next(e)
    try {
      const rate = e.rateLimits.length > 0 ? Math.max(...e.rateLimits.map(r => r.percentUsed)) : null
      await update($, figuresRef, () => ({
        contextPercent: e.context.percent ?? null,
        contextTokens: e.context.tokens ?? null,
        contextWindow: e.context.window ?? null,
        rateLimitPercent: rate,
      }))
    } catch {
      // Observing only.
    }
    return result
  })

  // One rm inside the shared 1.5 s bound, started beside core's end step rather
  // than before it, so a slow spawn never eats core's share; a crash never gets
  // here, so other sessions' ticks collect what is left.
  on('session.end', async ($, e, next) => {
    const [result] = await Promise.all([
      next(e),
      (async () => {
        const dir = await dataDir($)
        if (dir && isSessionId(e.sessionId)) await removeFile($, `${dir}/sessions/${e.sessionId}.json`)
      })(),
    ])
    return result
  })

  // Read-only, so any origin may run it, but only the person's own origins
  // (PANE_ORIGINS) open the focused pane. When the pane is placed the row says
  // only that (the row is read by the model and kept in the transcript). The
  // per-session table is the answer only to the person where the pane is not
  // placed, or where nothing draws; any other origin gets one summary line.
  on('command.run', { command: 'mem' }, async ($, e) => {
    let snapshot = await read($, snapshotRef)
    // A tick already in flight (the timer's) is not joined when a reading is
    // cached: its process waits are not this hook's, and /mem answers at once.
    if (!snapshot || (!running && (await $.clock.now()) - snapshot.at > REFRESH_AFTER_MS)) {
      snapshot = (await runTick($))?.snapshot ?? snapshot
    }
    // A plain -p run draws on no surface yet "places" every pane: answer it with the table.
    const surfaces = await $.session.surfaces().catch(() => [])
    const isPerson = PANE_ORIGINS.has(e.origin.kind)
    if (surfaces.length > 0 && isPerson) {
      let isPlaced = false
      try {
        isPlaced = (await openPane($)).isPlaced
      } catch {
        isPlaced = false
      }
      if (isPlaced) return { text: 'Memory pane opened.' }
    }
    if (!snapshot) return { text: 'mem-gauge: no reading yet (the collectors could not run).' }
    return { text: surfaces.length > 0 && !isPerson ? summaryLine(snapshot) : compactReport(snapshot, config.advice) }
  }).catch(async ($, e) => {
    // Past its budget or failed: answer from the last reading rather than leave
    // a registered command with no output.
    const snapshot = await read($, snapshotRef).catch(() => null)
    if (!snapshot) return { text: 'mem-gauge: no reading yet.' }
    return { text: PANE_ORIGINS.has(e.origin.kind) ? compactReport(snapshot, config.advice) : summaryLine(snapshot) }
  })

  on('command.run', { command: 'disk' }, async ($, e) => {
    const surfaces = await $.session.surfaces().catch(() => [])
    if (surfaces.length > 0 && PANE_ORIGINS.has(e.origin.kind)) {
      let isPlaced = false
      try {
        isPlaced = (await openDiskPane($)).isPlaced
      } catch {
        isPlaced = false
      }
      if (isPlaced) return { text: 'Disk pane opened.' }
    }
    const snapshot = await read($, snapshotRef)
    if (!snapshot) return { text: 'mem-gauge: no reading yet.' }
    return { text: diskLine(snapshot) }
  }).catch(async ($) => {
    const snapshot = await read($, snapshotRef).catch(() => null)
    return { text: snapshot ? diskLine(snapshot) : 'mem-gauge: no reading yet.' }
  })

  // The gauge on the terminal: the hint line under the prompt, after the engine's
  // own line so its pills stay live. Only the terminal raises the hint line to
  // plugins (the desktop host does not), so every other surface passes.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const engine = await next(e)
    if (e.surface !== 'terminal') return engine
    const snapshot = await read($, snapshotRef)
    if (!snapshot) return engine
    const wrap = await read($, wrapRef)
    const open = () => void openPane($).catch(() => undefined)
    // No vector element here: the quintile glyph in red stands in for the ring, and "Disk" for the icon.
    const { Box, Text, Button } = $.ui.resolve(e)
    return (
      <Box flexDirection="row">
        {engine}
        <Box marginLeft={2} flexDirection="row" gap={1}>
          <Text color="red" bold>{glyph(snapshot.machine.usedPercent)}</Text>
          <Button key="mem-gauge" plain dimColor label={statusLine(snapshot, wrap)} onPress={open} />
        </Box>
      </Box>
    )
  })

  // The gauge on the desktop: the prompt footer's mode row, the one site under
  // the composer the desktop raises. That strip clips what does not fit, draws
  // no vector element (an Svg there is simply absent), ignores a Box's hover
  // and display, draws every Button before every Text whatever the tree's
  // order, and a Button is the only thing it draws pressable, always as a
  // native chip; it draws no Client either. Joseph chose the chips: by
  // default the two figures are Buttons that open the panes, the memory
  // quintile ring with the used percent and the disk glyph with the free
  // space. With footerButtons off the row is plain text and /mem and /disk
  // open the panes. Pressure is read in the pane; under
  // pressure or a wrap request the memory figure reads "! 60%".
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const engine = await next(e)
    if (e.surface !== 'desktop') return engine
    const snapshot = await read($, snapshotRef)
    if (!snapshot) return engine
    const wrap = await read($, wrapRef)
    const m = snapshot.machine
    const { Box, Text, Button } = $.ui.resolve(e)
    const { used, disk, diskPct, alarm } = footerParts(snapshot, wrap)
    const openMemory = () => void openPane($).catch(() => undefined)
    const openDisk = () => void openDiskPane($).catch(() => undefined)
    if (config.footerButtons && config.footerCompact) {
      // Both figures in one tight chip (memory used %, disk used %), so the strip holds other mods' chips too; Disk is a button in the Memory pane.
      return (
        <Box flexDirection="row" alignItems="center" gap={1}>
          <Button key="mem-gauge" plain label={`${glyph(m.usedPercent)}${alarm ? '!' : ''}${used} ${DISK_GLYPH}${diskPct}`} onPress={openMemory} />
          {engine}
        </Box>
      )
    }
    if (config.footerButtons) {
      return (
        <Box flexDirection="row" alignItems="center" gap={1}>
          <Button key="mem-gauge" plain label={`${glyph(m.usedPercent)} ${alarm ? '! ' : ''}${used}`} onPress={openMemory} />
          <Button key="mem-gauge-disk" plain label={`${DISK_GLYPH} ${disk}`} onPress={openDisk} />
          {engine}
        </Box>
      )
    }
    if (config.footerCompact) {
      // Plain text, as tight as the one-chip label: both fullness percents, nothing pressable; /mem and /disk open the panes.
      return (
        <Box flexDirection="row" alignItems="center" gap={1}>
          <Text color="red" bold>
            {glyph(m.usedPercent)}
          </Text>
          {alarm ? <Text color="red" bold>{`!${used} ${DISK_GLYPH}${diskPct}`}</Text> : <Text>{`${used} ${DISK_GLYPH}${diskPct}`}</Text>}
          {engine}
        </Box>
      )
    }
    return (
      <Box flexDirection="row" alignItems="center" gap={1}>
        <Text color="red" bold>
          {glyph(m.usedPercent)}
        </Text>
        {alarm ? <Text color="red" bold>{`! ${used}`}</Text> : <Text>{used}</Text>}
        <Text dimColor>{`${DISK_GLYPH} ${disk}`}</Text>
        {engine}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const snapshot = await read($, snapshotRef)
    const asked = await read($, askedRef)
    const wrap = await read($, wrapRef)
    const showAll = await read($, showAllRef)
    const applying = await read($, applyingRef)
    const now = await $.clock.now()
    const cols = Math.max(24, Math.floor(e.props.bodyColumns))

    const controls = (
      <Box flexDirection="row" gap={2} marginTop={1}>
        <Button key="refresh" label="Refresh" hotkey="r" onPress={() => void runTick($)} />
        <Button key="disk" label="Disk" hotkey="d" onPress={() => void openDiskPane($).catch(() => undefined)} />
        <Button key="close" label="Close" hotkey="c" role="dismiss" onPress={() => void $.ui.close({ id: PANE }).catch(() => undefined)} />
      </Box>
    )
    if (!snapshot) {
      return (
        <Box flexDirection="column">
          <Text dimColor>Reading memory…</Text>
          {controls}
        </Box>
      )
    }

    const m = snapshot.machine
    const used = m.usedPercent === null ? '--' : `${Math.round(m.usedPercent)}%`
    let gauge
    if (e.surface === 'terminal') {
      gauge = <Text bold>{bar(m.usedPercent, Math.min(32, cols - 14))}</Text>
    } else {
      const { Svg } = $.ui.resolve(e)
      gauge = (
        <Svg source={ringSvg(m.usedPercent, m.pressure)} alt={`Memory ${used} used, pressure ${m.pressure}`} width={88} height={88} />
      )
    }

    // Label left, figure right-aligned in one column.
    const totals: readonly [string, string][] = [
      ['Used', `${formatBytes(m.usedBytes)} of ${formatBytes(m.totalBytes)}`],
      ['Free', formatBytes(m.freeBytes)],
      ['Compressed', formatBytes(m.compressedBytes)],
      ['Swap', `${formatBytes(m.swapUsedBytes)} of ${formatBytes(m.swapTotalBytes)}`],
      ['Load', `${m.load1 === null ? '?' : m.load1.toFixed(1)} on ${m.cores ?? '?'} cores`],
    ]
    // Label left in a fixed column, figure flush with the pane's right edge.
    const totalsLabelWidth = 12

    // Columns sized to the body; model and idle drop out first on a narrow pane.
    const isWide = cols >= 70
    const width = { rss: 9, ctx: 6, agents: 7, idle: isWide ? 9 : 0, model: isWide ? 14 : 0 }
    const labelWidth = Math.max(8, cols - width.rss - width.ctx - width.agents - width.idle - width.model)
    // Text columns (session, model) read from the left; figure columns
    // (RSS, context, agents, idle) sit at the right of their column, and the
    // session column takes whatever the row has left, so the figures line up
    // on the pane's right edge on every surface and font. This session is the
    // bold row (no mark column).
    const cell = (w: number, text: string, dim: boolean, bold: boolean, align: 'left' | 'right' = 'left', grows = false) => (
      <Box width={w} flexGrow={grows ? 1 : 0} justifyContent={align === 'right' ? 'flex-end' : 'flex-start'}>
        <Text wrap="truncate" dimColor={dim} bold={bold}>
          {text}
        </Text>
      </Box>
    )
    const tableRow = (key: string, values: string[], dim: boolean, bold: boolean) => (
      <Box key={key} flexDirection="row">
        {cell(labelWidth, values[0] ?? '', dim, bold, 'left', true)}
        {isWide && cell(width.model, values[1] ?? '', dim, bold)}
        {cell(width.rss, values[2] ?? '', dim, bold, 'right')}
        {cell(width.ctx, values[3] ?? '', dim, bold, 'right')}
        {cell(width.agents, values[4] ?? '', dim, bold, 'right')}
        {isWide && cell(width.idle, values[5] ?? '', dim, bold, 'right')}
      </Box>
    )
    const live = snapshot.sessions.filter(s => s.status === 'live')
    // Active (not exited) sessions, biggest first; the top ten until View all.
    const active = snapshot.sessions.filter(s => s.status !== 'gone').sort((a, b) => (b.rssMB ?? -1) - (a.rssMB ?? -1))
    const listed = showAll ? active : active.slice(0, TOP_SESSIONS)
    const hidden = active.length - listed.length
    const toggle = (value: boolean) => void update($, showAllRef, () => value)
    const tips = advise(snapshot, config.advice)
    const rowsById = new Map(snapshot.sessions.map(s => [s.sessionId, s]))

    return (
      <Box flexDirection="column">
        {wrap && (
          <Text bold>
            ! Another session asked this one to wrap up
            {wrap.freesMB === null ? '' : ` (frees about ${formatMB(wrap.freesMB)})`}. Nothing runs on its own.
          </Text>
        )}
        <Box key="gauge" flexDirection="row" gap={2} alignItems="center">
          {gauge}
          <Box flexDirection="column">
            <Text bold>
              Memory {used} used · pressure {m.pressure}
            </Text>
            <Text dimColor>
              This session {snapshot.thisSessionMB === null ? 'unknown' : formatMB(snapshot.thisSessionMB)} · {live.length} live
              session{live.length === 1 ? '' : 's'}
            </Text>
          </Box>
        </Box>
        <Box flexDirection="column" marginTop={1}>
          {totals.map(([label, value]) => (
            <Box key={`total:${label}`} flexDirection="row">
              <Box width={totalsLabelWidth}>
                <Text dimColor>{label}</Text>
              </Box>
              <Box flexGrow={1} justifyContent="flex-end">
                <Text wrap="truncate">{value}</Text>
              </Box>
            </Box>
          ))}
        </Box>

        <Box key="sessions" flexDirection="column" marginTop={1}>
          <Text bold>
            Sessions{active.length > TOP_SESSIONS ? (showAll ? ` (all ${active.length} active)` : ` (top ${TOP_SESSIONS} of ${active.length} active)`) : ''}
          </Text>
          {tableRow('head', ['Session', 'Model', 'RSS', 'Ctx', 'Agents', 'Idle'], true, false)}
          {listed.map(s =>
            tableRow(
              `s:${s.sessionId}`,
              [
                s.status === 'live' ? s.label : `${s.label} (${s.status})`,
                s.hasMod === false ? '--' : shortModel(s.model),
                formatMB(s.rssMB),
                s.contextPercent === null ? '--' : `${Math.round(s.contextPercent)}%`,
                s.hasMod === false ? '--' : String(s.agents),
                s.idleMinutes === null ? '--' : `${s.idleMinutes}m`,
              ],
              s.status !== 'live',
              s.isThis,
            ),
          )}
          {hidden > 0 && (
            <Box marginTop={1}>
              <Button key="sessions-all" label={`View all (${active.length})`} hotkey="a" onPress={() => toggle(true)} />
            </Box>
          )}
          {showAll && active.length > TOP_SESSIONS && (
            <Box marginTop={1}>
              <Button key="sessions-top" label={`View top ${TOP_SESSIONS}`} hotkey="a" onPress={() => toggle(false)} />
            </Box>
          )}
          {snapshot.unregistered !== null && snapshot.unregistered.count > 0 && (
            <Text dimColor wrap="truncate">
              + {snapshot.unregistered.count} Claude session{snapshot.unregistered.count === 1 ? '' : 's'} without a session record:{' '}
              {formatMB(snapshot.unregistered.rssMB)}
            </Text>
          )}
        </Box>

        {snapshot.topApps.length > 0 && (
          <Box key="apps" flexDirection="column" marginTop={1}>
            <Text bold>Other apps</Text>
            {snapshot.topApps.map(app => (
              <Box key={`app:${app.name}`} flexDirection="row">
                <Box width={Math.max(8, cols - 10)} flexGrow={1}>
                  <Text wrap="truncate">{app.name}</Text>
                </Box>
                <Box width={10} justifyContent="flex-end">
                  <Text>{formatMB(app.rssMB)}</Text>
                </Box>
              </Box>
            ))}
          </Box>
        )}

        <Box key="optimize" flexDirection="column" marginTop={1}>
          <Text bold>Optimize</Text>
          {tips.length === 0 && <Text dimColor>Nothing to do right now.</Text>}
          {tips.map(tip => {
            const target = tip.sessionId ? rowsById.get(tip.sessionId) : undefined
            const askedAt = target ? asked[target.sessionId] : undefined
            const isRecent = tip.action?.kind === 'ask-wrap' && askedAt !== undefined && now - askedAt < ASK_EVERY_MS
            const inFlight = applying.includes(`memory:${tip.key}`)
            // While one of the tip's two actions runs, the other is dim (and its press is ignored in applyMemory / runHandoff).
            const isHandingOff = applying.includes(`handoff:${tip.key}`)
            // One block per tip, a blank line between tips: the text, then its buttons on their own row
            // beneath it (none for a tip with nothing safe to automate).
            return (
              <Box key={`tip:${tip.key}`} flexDirection="column" marginTop={1}>
                <Text wrap="wrap">{tip.text}</Text>
                {(tip.action || tip.secondary) && (
                  <Box flexDirection="row" gap={1}>
                    {tip.action && (
                      <Button
                        key={`apply:${tip.key}`}
                        label={isRecent ? 'Asked' : inFlight ? 'Applying…' : actionLabel(tip.action)}
                        dimColor={isRecent || inFlight || isHandingOff}
                        onPress={() => void applyMemory($, tip, rowsById).catch(() => undefined)}
                      />
                    )}
                    {tip.secondary && (
                      <Button
                        key={`handoff:${tip.key}`}
                        label={actionLabel(tip.secondary)}
                        dimColor={isHandingOff || inFlight}
                        onPress={() => void applyMemory($, tip, rowsById, tip.secondary).catch(() => undefined)}
                      />
                    )}
                  </Box>
                )}
              </Box>
            )
          })}
        </Box>

        <Box marginTop={1}>
          <Text dimColor wrap="wrap">
            RSS is approximate (it undercounts compressed memory). A session without mem-gauge is listed from the
            engine's own record: name, memory and idle time only (model, context and agents read --).
          </Text>
        </Box>
        {controls}
      </Box>
    )
  })

  // The disk pane: the volume's use, every mounted volume, and the usual big folders.
  on('ui.render', { component: 'Pane', requestId: DISK_PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const snapshot = await read($, snapshotRef)
    const report = await read($, diskRef)
    const applying = await read($, applyingRef)
    const cols = Math.max(24, Math.floor(e.props.bodyColumns))

    const controls = (
      <Box flexDirection="row" gap={2} marginTop={1}>
        <Button key="disk-refresh" label="Refresh" hotkey="r" onPress={() => void runDiskScan($)} />
        <Button key="disk-close" label="Close" hotkey="c" role="dismiss" onPress={() => void $.ui.close({ id: DISK_PANE }).catch(() => undefined)} />
      </Box>
    )
    const m = snapshot?.machine ?? null
    const usedBytes = m && m.diskTotalBytes !== null && m.diskFreeBytes !== null ? Math.max(0, m.diskTotalBytes - m.diskFreeBytes) : null
    const usedPercent = m && usedBytes !== null && m.diskTotalBytes ? (usedBytes / m.diskTotalBytes) * 100 : null
    const used = usedPercent === null ? '--' : `${Math.round(usedPercent)}%`
    let gauge
    if (e.surface === 'terminal') {
      gauge = <Text bold>{bar(usedPercent, Math.min(32, cols - 14))}</Text>
    } else {
      const { Svg } = $.ui.resolve(e)
      gauge = <Svg source={ringSvg(usedPercent, 'ok', 88, true, `Disk ${used} used`)} alt={`Disk ${used} used`} width={88} height={88} />
    }

    const isWide = cols >= 64
    const sizeWidth = 10
    const nameWidth = Math.max(8, cols - sizeWidth * (isWide ? 4 : 2))
    // The volume name reads from the left and takes the row's slack; every
    // size column sits at the right of its column, flush with the pane's edge.
    const cell = (w: number, text: string, dim: boolean, bold = false, align: 'left' | 'right' = 'left', grows = false) => (
      <Box width={w} flexGrow={grows ? 1 : 0} justifyContent={align === 'right' ? 'flex-end' : 'flex-start'}>
        <Text wrap="truncate" dimColor={dim} bold={bold}>
          {text}
        </Text>
      </Box>
    )
    const volumeRow = (key: string, values: string[], dim: boolean, bold = false) => (
      <Box key={key} flexDirection="row">
        {cell(nameWidth, values[0] ?? '', dim, bold, 'left', true)}
        {isWide && cell(sizeWidth, values[1] ?? '', dim, bold, 'right')}
        {isWide && cell(sizeWidth, values[2] ?? '', dim, bold, 'right')}
        {cell(sizeWidth, values[3] ?? '', dim, bold, 'right')}
        {cell(sizeWidth, values[4] ?? '', dim, bold, 'right')}
      </Box>
    )

    return (
      <Box flexDirection="column">
        {m ? (
          <Box key="gauge" flexDirection="row" gap={2} alignItems="center">
            {gauge}
            <Box flexDirection="column">
              <Text bold>Disk {used} used</Text>
              <Text dimColor>
                used {formatBytes(usedBytes)} of {formatBytes(m.diskTotalBytes)} · free {formatBytes(m.diskFreeBytes)}
              </Text>
            </Box>
          </Box>
        ) : (
          <Text dimColor>Reading disk…</Text>
        )}

        <Box key="volumes" flexDirection="column" marginTop={1}>
          <Text bold>Volumes</Text>
          {!report && <Text dimColor>Reading volumes and folders…</Text>}
          {report && volumeRow('head', ['Volume', 'Size', 'Used', 'Free', 'Used %'], true)}
          {report?.volumes.map(v =>
            volumeRow(
              `v:${v.mount}`,
              [v.name, formatBytes(v.totalBytes), formatBytes(v.usedBytes), formatBytes(v.freeBytes), `${Math.round((v.usedBytes / v.totalBytes) * 100)}%`],
              false,
              v.name === 'Macintosh HD',
            ),
          )}
          {report && report.volumes.length === 0 && <Text dimColor>df listed no volume.</Text>}
        </Box>

        {report && (
          <Box key="folders" flexDirection="column" marginTop={1}>
            <Text bold>Big folders</Text>
            {report.folders.map(f => (
              <Box key={`f:${f.path}`} flexDirection="row">
                <Box width={Math.max(8, cols - sizeWidth)} flexGrow={1}>
                  <Text wrap="truncate" dimColor={f.bytes === null}>
                    {f.label}
                  </Text>
                </Box>
                <Box width={sizeWidth} justifyContent="flex-end">
                  <Text dimColor={f.bytes === null}>{f.bytes === null ? '--' : formatBytes(f.bytes)}</Text>
                </Box>
              </Box>
            ))}
          </Box>
        )}

        {report && (
          <Box key="free" flexDirection="column" marginTop={1}>
            <Text bold>Free up safely</Text>
            {diskAdvice(report).length === 0 && <Text dimColor>Nothing worth freeing right now.</Text>}
            {diskAdvice(report).map(tip => {
              const inFlight = applying.includes(`disk:${tip.key}`)
              // The same shape as the Memory pane's tips: one block each, the button on its own row beneath.
              return (
                <Box key={`free:${tip.key}`} flexDirection="column" marginTop={1}>
                  <Text wrap="wrap">{tip.text}</Text>
                  {tip.action && (
                    <Box flexDirection="row" gap={1}>
                      <Button
                        key={`apply:${tip.key}`}
                        label={inFlight ? 'Applying…' : APPLY}
                        dimColor={inFlight}
                        onPress={() => void applyDisk($, tip).catch(() => undefined)}
                      />
                    </Box>
                  )}
                </Box>
              )
            })}
          </Box>
        )}

        <Box marginTop={1}>
          <Text dimColor wrap="wrap">
            Sizes come from df (5 s) and du (10 s each, on open and Refresh); a folder that is missing or takes longer shows --.
          </Text>
        </Box>
        {controls}
      </Box>
    )
  })
}

files.hooks/advice.ts:
// The OPTIMIZE section: fixed rules over a snapshot, no model call. Each rule
// names the session or app it is about and the memory a step would free, so
// the person can act on it without opening Activity Monitor.

import type { DiskReport, Snapshot } from '../types'

import { formatBytes, formatMB, formatTokens, pressureText, shortModel } from './parse'

/**
 * What a Memory pane tip's button does. Every kind confirms first and runs a
 * fixed command or an existing flow; none takes text from a process or a file
 * into a shell (there is no shell: argv only). `hand-off` runs /handoff, the
 * handoff mod's command, whose own dialog confirms before it writes a note and
 * clears the conversation (register.tsx `runHandoff`).
 */
export type AdviceAction =
  | { kind: 'ask-wrap'; sessionId: string }
  | { kind: 'compact' }
  | { kind: 'hand-off' }
  | { kind: 'quit-app'; app: string }
  | { kind: 'open-disk' }

export type Advice = {
  /** Stable key per rule and target, for list keys and tests. */
  key: string
  text: string
  /** The session this advice targets, when the pane may offer "Ask to wrap". */
  sessionId?: string
  /** What the tip's button does; absent, the tip is advice only (sequence agents, pause suites, a session with no mod). */
  action?: AdviceAction
  /** A second button beside it, where a tip offers two ways out (this session's context: Compact, or Hand off). */
  secondary?: AdviceAction
}

/** What the Disk pane's Apply button does for a tip; each a fixed argv (diskActionArgv). */
export type DiskAction = { kind: 'clear-caches' | 'clear-derived-data' | 'delete-stale-simulators' | 'empty-trash' | 'prune-file-history' }

export type DiskAdvice = { key: string; text: string; action?: DiskAction }

export type AdviceOptions = {
  idleMinutes: number
  /** The context tip fires at this many tokens; 0 falls back to CONTEXT_HIGH percent of the window. */
  contextTokens: number
}

const IDLE_BIG_MB = 1024
// The percent rule is the fallback for a session whose token count is unknown, or an option of 0.
const CONTEXT_HIGH = 80
const AGENTS_HIGH = 3
const USED_HIGH = 85
const DISK_LOW_BYTES = 10 * 1024 ** 3

/** The sessions the pane offers "Ask to wrap" for: other live sessions idle past the threshold and over 1 GB. */
export function idleSessions(snapshot: Snapshot, options: AdviceOptions) {
  return snapshot.sessions.filter(
    s =>
      !s.isThis &&
      s.status === 'live' &&
      s.idleMinutes !== null &&
      s.idleMinutes > options.idleMinutes &&
      (s.rssMB ?? 0) > IDLE_BIG_MB,
  )
}

export function advise(snapshot: Snapshot, options: AdviceOptions): Advice[] {
  const out: Advice[] = []
  const live = snapshot.sessions.filter(s => s.status === 'live')
  const m = snapshot.machine

  for (const s of idleSessions(snapshot, options)) {
    out.push({
      key: `idle:${s.sessionId}`,
      sessionId: s.sessionId,
      ...(s.hasMod === false ? {} : { action: { kind: 'ask-wrap' as const, sessionId: s.sessionId } }),
      // A row an earlier build kept in $.state has no hasMod; only an explicit false means no mod to ask.
      text:
        s.hasMod === false
          ? `${s.label}: idle ${s.idleMinutes} min, archive it from the sidebar (frees ${formatMB(s.rssMB)})`
          : `${s.label}: idle ${s.idleMinutes} min, wrap or archive (frees ${formatMB(s.rssMB)})`,
    })
  }

  for (const s of live) {
    const tokens = s.contextTokens
    const high =
      options.contextTokens > 0 && tokens !== null
        ? tokens >= options.contextTokens
        : s.contextPercent !== null && s.contextPercent > CONTEXT_HIGH
    if (high) {
      const pct = s.contextPercent === null ? null : Math.round(s.contextPercent)
      const ctx =
        tokens !== null && pct !== null ? `${formatTokens(tokens)} (${pct}%)` : pct !== null ? `${pct}%` : formatTokens(tokens)
      // Only this session can be compacted or handed off from here; another's tip is advice only.
      out.push(
        s.isThis
          ? {
              key: `context:${s.sessionId}`,
              action: { kind: 'compact' },
              secondary: { kind: 'hand-off' },
              text: `${s.label}: context ${ctx}. Compact to keep going mid-task, or hand off at the next milestone (a note is written for the fresh session).`,
            }
          : { key: `context:${s.sessionId}`, text: `${s.label}: context ${ctx}, compact or hand off from there` },
      )
    }
  }

  const fanOut = live.filter(s => s.agents > AGENTS_HIGH).sort((a, b) => b.agents - a.agents)[0]
  if (fanOut) {
    out.push({
      key: `agents:${fanOut.sessionId}`,
      text: `${fanOut.label}: ${fanOut.agents} agents running, the largest fan-out; consider sequencing`,
    })
  }

  const isTight = (m.usedPercent !== null && m.usedPercent > USED_HIGH) || m.pressure === 'warn' || m.pressure === 'critical'
  const topApp = snapshot.topApps[0]
  if (isTight && topApp) {
    // No quit for the host of this very session (the Claude desktop app) or a bare engine: advice only.
    const isHost = /^claude(\.exe)?$/i.test(topApp.name)
    out.push({ key: 'app', ...(isHost ? {} : { action: { kind: 'quit-app' as const, app: topApp.name } }), text: `memory is tight: close ${topApp.name} (${formatMB(topApp.rssMB)})` })
  }

  if (m.load1 !== null && m.cores !== null && m.cores > 0 && m.load1 > 2 * m.cores) {
    out.push({ key: 'load', text: `load ${m.load1.toFixed(1)} on ${m.cores} cores: pause heavy test suites` })
  }

  if (m.diskFreeBytes !== null && m.diskFreeBytes < DISK_LOW_BYTES) {
    out.push({ key: 'disk', action: { kind: 'open-disk' }, text: `disk ${formatBytes(m.diskFreeBytes)} free: see the Disk pane for what is safe to free` })
  }

  return out
}

/**
 * The /mem answer to an origin that is not the person, in a session that can
 * draw: machine figures and a count only, so no other session's label, model
 * or size lands in this transcript on a peer's, a plugin's or a schedule's say-so.
 */
export function summaryLine(snapshot: Snapshot): string {
  const m = snapshot.machine
  const used = m.usedPercent === null ? '--' : `${Math.round(m.usedPercent)}%`
  const live = snapshot.sessions.filter(s => s.status === 'live').length
  return `Memory ${used} used · Pressure ${pressureText(m.pressure)} · ${live} live session${live === 1 ? '' : 's'}`
}

/**
 * The /mem answer where no pane can be drawn (a -p run, an unplaced pane). It
 * becomes a transcript row the model reads, so it carries labels (repo and
 * branch) but never a cwd, and at most ten sessions.
 */
export function compactReport(snapshot: Snapshot, options: AdviceOptions): string {
  const m = snapshot.machine
  const used = m.usedPercent === null ? '--' : `${Math.round(m.usedPercent)}%`
  const lines = [
    `Memory ${used} used (${formatBytes(m.usedBytes)} of ${formatBytes(m.totalBytes)}) · ` +
      `Pressure ${pressureText(m.pressure)} · compressed ${formatBytes(m.compressedBytes)} · ` +
      `swap ${formatBytes(m.swapUsedBytes)} of ${formatBytes(m.swapTotalBytes)} · ` +
      `load ${m.load1 === null ? '?' : m.load1.toFixed(1)} on ${m.cores ?? '?'} cores · disk ${formatBytes(m.diskFreeBytes)} free`,
    `This session: ${snapshot.thisSessionMB === null ? 'unknown' : formatMB(snapshot.thisSessionMB)} (approximate RSS)`,
  ]
  const live = snapshot.sessions.filter(s => s.status === 'live')
  lines.push(`Sessions (${live.length} live):`)
  for (const s of snapshot.sessions.slice(0, 10)) {
    const ctx = s.contextPercent === null ? 'ctx --' : `ctx ${Math.round(s.contextPercent)}%`
    const idle = s.idleMinutes === null ? 'idle --' : `idle ${s.idleMinutes}m`
    const tag = s.status === 'live' ? '' : ` (${s.status})`
    lines.push(
      `  ${s.isThis ? '*' : '-'} ${s.label} · ${shortModel(s.model)} · ${formatMB(s.rssMB)} · ${ctx} · ${s.agents} agents · ${idle}${tag}`,
    )
  }
  const other = snapshot.unregistered
  if (other && other.count > 0) {
    lines.push(`  + ${other.count} Claude session${other.count === 1 ? '' : 's'} without mem-gauge: ${formatMB(other.rssMB)}`)
  }
  if (snapshot.topApps.length > 0) {
    lines.push(`Top apps: ${snapshot.topApps.map(a => `${a.name} ${formatMB(a.rssMB)}`).join(', ')}`)
  }
  const tips = advise(snapshot, options)
  lines.push(tips.length === 0 ? 'Optimize: nothing to do.' : 'Optimize:')
  for (const tip of tips) lines.push(`  - ${tip.text}`)
  return lines.join('\n')
}

/** A folder counts as worth mentioning in the disk advice from this size. */
const DISK_TIP_MIN_BYTES = 512 * 1024 * 1024

/**
 * What is safe to free on the disk, from the Disk pane's folder sizes and
 * volumes: caches, build products, stale simulators, the Trash, old file
 * history. Only things that can be cleared are listed; the Claude transcripts
 * are the session history and never appear. Pure; drawn as plain lines.
 */
export function diskAdvice(report: DiskReport): DiskAdvice[] {
  const out: DiskAdvice[] = []
  const size = (suffix: string): number | null => {
    const f = report.folders.find(folder => folder.path.endsWith(suffix))
    return f && f.bytes !== null ? f.bytes : null
  }
  const big = (suffix: string): number | null => {
    const b = size(suffix)
    return b !== null && b >= DISK_TIP_MIN_BYTES ? b : null
  }
  const caches = big('/Library/Caches')
  if (caches !== null) out.push({ key: 'caches', action: { kind: 'clear-caches' }, text: `Library caches ${formatBytes(caches)}: safe to clear; apps rebuild what they need` })
  const derived = big('/Library/Developer/Xcode/DerivedData')
  if (derived !== null) out.push({ key: 'derived', action: { kind: 'clear-derived-data' }, text: `Xcode DerivedData ${formatBytes(derived)}: safe to delete; the next build of each project is a full one` })
  const devices = big('/Library/Developer/CoreSimulator/Devices')
  if (devices !== null) {
    out.push({
      key: 'simulators',
      action: { kind: 'delete-stale-simulators' },
      text: `iOS simulator devices ${formatBytes(devices)}: delete the simulators you no longer test on (Apply removes the unavailable ones, xcrun simctl delete unavailable)`,
    })
  }
  const runtimes = report.volumes.filter(v => v.name.startsWith('Simulator runtime '))
  if (runtimes.length > 1) {
    const total = runtimes.reduce((sum, v) => sum + v.usedBytes, 0)
    out.push({ key: 'runtimes', text: `${runtimes.length} iOS simulator runtimes ${formatBytes(total)}: keep the one you test on; remove the rest in Xcode > Settings > Components` })
  }
  const trash = big('/.Trash')
  if (trash !== null) out.push({ key: 'trash', action: { kind: 'empty-trash' }, text: `Trash ${formatBytes(trash)}: empty it` })
  const history = big('/.claude/file-history')
  if (history !== null) {
    out.push({
      key: 'file-history',
      action: { kind: 'prune-file-history' },
      text: `Claude file history ${formatBytes(history)}: file snapshots for rewinding edits; safe to prune once those sessions are closed (Apply removes entries older than 30 days)`,
    })
  }
  // The Claude transcripts (~/.claude/projects) are the session history: never a candidate, so never listed here.
  return out
}

/** The one command an Apply runs for a disk action, as argv (no shell): fixed paths under `home`, nothing from a file or a process. */
export function diskActionArgv(action: DiskAction, home: string): string[] {
  // No -H: a target folder that is itself a symlink is not followed (find lists nothing, rm removes nothing),
  // so a relocated Caches is left alone rather than a link to anywhere being emptied; entries that are links are removed as links.
  const clear = (dir: string) => ['find', dir, '-mindepth', '1', '-maxdepth', '1', '-exec', 'rm', '-rf', '{}', '+']
  switch (action.kind) {
    case 'clear-caches':
      return clear(`${home}/Library/Caches`)
    case 'clear-derived-data':
      return clear(`${home}/Library/Developer/Xcode/DerivedData`)
    case 'delete-stale-simulators':
      return ['xcrun', 'simctl', 'delete', 'unavailable']
    case 'empty-trash':
      return clear(`${home}/.Trash`)
    case 'prune-file-history':
      return ['find', `${home}/.claude/file-history`, '-mindepth', '1', '-maxdepth', '1', '-mtime', '+30', '-exec', 'rm', '-rf', '{}', '+']
  }
}

/** What the confirmation asks before a disk action runs; ends with what cannot be undone. */
export function diskActionQuestion(action: DiskAction): string {
  switch (action.kind) {
    case 'clear-caches':
      return 'Clear everything in ~/Library/Caches (apps rebuild their caches; this cannot be undone)?'
    case 'clear-derived-data':
      return 'Delete everything in Xcode DerivedData (the next build of each project is a full one; this cannot be undone)?'
    case 'delete-stale-simulators':
      return 'Delete the unavailable iOS simulators, those whose runtime is gone (the ones you still test on are kept)?'
    case 'empty-trash':
      return 'Empty the Trash (everything in it is deleted for good)?'
    case 'prune-file-history':
      return 'Delete Claude file-history entries older than 30 days (rewinding edits in those sessions will no longer be possible)?'
  }
}

/** A short name for a disk action, for toasts. */
export function diskActionLabel(action: DiskAction): string {
  switch (action.kind) {
    case 'clear-caches':
      return 'clear Library caches'
    case 'clear-derived-data':
      return 'delete Xcode DerivedData'
    case 'delete-stale-simulators':
      return 'delete unavailable simulators'
    case 'empty-trash':
      return 'empty the Trash'
    case 'prune-file-history':
      return 'prune old Claude file history'
  }
}

/**
 * A graceful quit of one app by name through osascript, the name handed as an
 * argument (never spliced into the script): the app may still ask to save.
 * Null for a name osascript could read as an option or that is not one line.
 */
export function quitAppArgv(app: string): string[] | null {
  if (!app || app.startsWith('-') || /[\u0000-\u001f\u007f]/.test(app) || app.length > 120) return null
  return ['osascript', '-e', 'on run argv', '-e', 'tell application (item 1 of argv) to quit', '-e', 'end run', app]
}

/**
 * A HOME an Apply may build paths under: absolute, no `.` or `..` segment
 * (so it cannot spell the disk root as `/.` or `/Users/..`), at least one
 * segment, no control characters. Null otherwise: the Apply says so and stops.
 */
export function applyHome(home: string | null): string | null {
  if (!home || !home.startsWith('/') || /[\u0000-\u001f\u007f]/.test(home)) return null
  const segments = home.split('/').filter(part => part !== '')
  if (segments.length === 0 || segments.some(part => part === '.' || part === '..')) return null
  return `/${segments.join('/')}`
}

files.hooks/parse.ts:
// Pure parsers and arithmetic for mem-gauge: every macOS command's text goes in,
// plain numbers come out. Nothing here touches `$`, so each function is tested
// from fixtures alone (hooks/parse.test.ts) and a parse failure is a null field,
// never a thrown tick.

import type { AppUsage, MachineStats, Pressure, SessionRow, SessionStatus, Snapshot, VolumeRow, WrapRequest } from '../types'

const MB = 1024 * 1024
const GB = 1024 * MB

/** A heartbeat older than this is stale and left out of totals. */
export const STALE_MS = 120_000
/** A gone or stale entry older than this is garbage-collected (a crash never fires session.end). */
export const GC_MS = 10 * 60_000
/** Any entry this old is collected whatever its pid says. */
export const MAX_AGE_MS = 24 * 60 * 60_000

/** `sysctl a b c` (no -n) into name -> value; keyed so a missing name cannot shift the others. */
export function parseSysctl(stdout: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const line of stdout.split('\n')) {
    const at = line.indexOf(':')
    if (at <= 0) continue
    const name = line.slice(0, at).trim()
    // sysctl names are dotted (hw.memsize); this also skips a stray "sysctl: unknown oid" line.
    if (!/^[a-z0-9_]+(\.[a-z0-9_]+)+$/i.test(name)) continue
    out[name] = line.slice(at + 1).trim()
  }
  return out
}

const toInt = (text: string | undefined): number | null => {
  if (text === undefined || !/^\d+$/.test(text.trim())) return null
  const n = Number(text.trim())
  return Number.isSafeInteger(n) ? n : null
}

export type VmStat = { pageSize: number; pages: Record<string, number> }

/**
 * `vm_stat`: the page size from its header and every "<label>: <n>." row, keyed
 * by the label lower-cased with a leading "Pages " dropped ("free", "wired down",
 * "occupied by compressor"). Null when the header is missing.
 */
export function parseVmStat(stdout: string): VmStat | null {
  const header = /page size of (\d+) bytes/.exec(stdout)
  const pageSize = header ? Number(header[1]) : NaN
  if (!Number.isSafeInteger(pageSize) || pageSize <= 0) return null
  const pages: Record<string, number> = {}
  for (const line of stdout.split('\n')) {
    const row = /^\s*"?([^:"]+)"?:\s+(\d+)\.?\s*$/.exec(line)
    if (!row) continue
    const label = row[1]!.trim().toLowerCase().replace(/^pages\s+/, '')
    pages[label] = Number(row[2])
  }
  return { pageSize, pages }
}

const UNIT: Record<string, number> = { K: 1024, M: MB, G: GB, T: GB * 1024 }

/** `vm.swapusage`: "total = 1024.00M  used = 202.00M  free = 822.00M  (encrypted)". */
export function parseSwap(value: string | undefined): { totalBytes: number; usedBytes: number } | null {
  if (!value) return null
  const read = (name: string) => {
    const m = new RegExp(`${name}\\s*=\\s*([\\d.]+)([KMGT])`).exec(value)
    return m ? Math.round(Number(m[1]) * UNIT[m[2]!]!) : null
  }
  const totalBytes = read('total')
  const usedBytes = read('used')
  return totalBytes === null || usedBytes === null ? null : { totalBytes, usedBytes }
}

/** `vm.loadavg`: "{ 1.52 1.80 1.95 }" -> the 1-minute figure. */
export function parseLoad(value: string | undefined): number | null {
  const m = value ? /^\{?\s*([\d.]+)/.exec(value) : null
  const n = m ? Number(m[1]) : NaN
  return Number.isFinite(n) ? n : null
}

/** `df -k /`: the data row's 1024-blocks and Available columns, in bytes. */
export function parseDf(stdout: string): { totalBytes: number; freeBytes: number } | null {
  for (const line of stdout.split('\n').slice(1)) {
    // The filesystem name may hold spaces, so anchor on the numeric run and the capacity's %.
    const m = /^(.*?)\s+(\d+)\s+(\d+)\s+(\d+)\s+\d+%/.exec(line)
    if (m) return { totalBytes: Number(m[2]) * 1024, freeBytes: Number(m[4]) * 1024 }
  }
  return null
}

/** Mounts `df -kP` lists that are no volume of the person's: the sealed-system helpers and the swap space. */
const HELPER_MOUNTS = new Set([
  '/dev',
  '/System/Volumes/VM',
  '/System/Volumes/Preboot',
  '/System/Volumes/Update',
  '/System/Volumes/xarts',
  '/System/Volumes/iSCPreboot',
  '/System/Volumes/Hardware',
])

/** A readable name for a mount point: the APFS system and data volumes, an external disk, a simulator runtime. */
export function volumeName(mount: string): string {
  if (mount === '/') return 'Macintosh HD (system)'
  if (mount === '/System/Volumes/Data') return 'Macintosh HD (data)'
  const sim = /^\/Library\/Developer\/CoreSimulator\/Volumes\/(.+)$/.exec(mount)
  if (sim) return `Simulator runtime ${sim[1]}`
  const vol = /^\/Volumes\/(.+)$/.exec(mount)
  if (vol) return vol[1]!
  return mount
}

/**
 * Every real volume in `df -kP` (POSIX columns: blocks, used, available,
 * capacity, mount), the pseudo filesystems (devfs, automounter maps) and the
 * helper mounts left out. The mount point may hold spaces.
 */
export function parseDfAll(stdout: string): VolumeRow[] {
  const rows: VolumeRow[] = []
  for (const line of stdout.split('\n').slice(1)) {
    const m = /^(.*?)\s+(\d+)\s+(\d+)\s+(\d+)\s+\d+%\s+(\/.*?)\s*$/.exec(line)
    if (!m) continue
    const filesystem = m[1]!
    const mount = m[5]!
    if (filesystem === 'devfs' || filesystem.startsWith('map ') || HELPER_MOUNTS.has(mount) || mount.startsWith('/System/Volumes/Data/')) continue
    const totalBytes = Number(m[2]) * 1024
    if (!(totalBytes > 0)) continue
    // A mount point is another program's text (a disk named elsewhere, a network share): one line,
    // no control characters, like every ps name and heartbeat label, or the pane is refused whole.
    const cleanMount = oneLine(mount.slice(0, 1024), 256)
    if (!cleanMount) continue
    const name = oneLine(volumeName(mount).slice(0, 512), 120) || cleanMount
    rows.push({ mount: cleanMount, name, totalBytes, usedBytes: Number(m[3]) * 1024, freeBytes: Number(m[4]) * 1024 })
  }
  return mergeSystemVolume(rows)
}

/**
 * The APFS system volume (`/`) and data volume (`/System/Volumes/Data`) share
 * one container, so df lists the same size and free space twice: one
 * "Macintosh HD" row, its used space the two volumes' together.
 */
function mergeSystemVolume(rows: VolumeRow[]): VolumeRow[] {
  const system = rows.find(r => r.mount === '/')
  const data = rows.find(r => r.mount === '/System/Volumes/Data')
  const main = data ?? system
  if (!main) return rows
  const merged: VolumeRow = {
    mount: '/',
    name: 'Macintosh HD',
    totalBytes: main.totalBytes,
    usedBytes: (system?.usedBytes ?? 0) + (data?.usedBytes ?? 0),
    freeBytes: main.freeBytes,
  }
  return [merged, ...rows.filter(r => r !== system && r !== data)]
}

/** One line for /disk where no pane can be drawn: 'Disk 50% used · used 931 GB of 1858 GB · free 927 GB'. */
export function diskLine(snapshot: Snapshot): string {
  const m = snapshot.machine
  const usedBytes = m.diskTotalBytes !== null && m.diskFreeBytes !== null ? Math.max(0, m.diskTotalBytes - m.diskFreeBytes) : null
  const percent = usedBytes !== null && m.diskTotalBytes ? `${Math.round((usedBytes / m.diskTotalBytes) * 100)}%` : '--'
  return `Disk ${percent} used · used ${formatCompact(usedBytes)} of ${formatCompact(m.diskTotalBytes)} · free ${formatCompact(m.diskFreeBytes)}`
}

/** `du -sk <path>` as bytes; null when du said nothing readable. */
export function parseDu(stdout: string): number | null {
  const m = /^\s*(\d+)\s/.exec(stdout)
  return m ? Number(m[1]) * 1024 : null
}

/**
 * Pressure from kern.memorystatus_level (percent of memory free as the kernel
 * judges it): under 20 warn, under 10 critical. Falls back to the share of
 * reclaimable pages from vm_stat when the sysctl is missing.
 */
export function pressureOf(level: number | null, vm: VmStat | null, totalBytes: number | null): Pressure {
  let freePercent = level
  if (freePercent === null && vm && totalBytes) {
    const p = vm.pages
    const reclaimable = (p['free'] ?? 0) + (p['inactive'] ?? 0) + (p['speculative'] ?? 0)
    freePercent = ((reclaimable * vm.pageSize) / totalBytes) * 100
  }
  if (freePercent === null || !Number.isFinite(freePercent)) return 'unknown'
  if (freePercent < 10) return 'critical'
  if (freePercent < 20) return 'warn'
  return 'ok'
}

/** One machine reading from the raw command outputs (any of them null when its command failed). */
export function buildMachine(
  at: number,
  raw: { sysctl: string | null; vmStat: string | null; df: string | null },
): MachineStats {
  const ctl = raw.sysctl ? parseSysctl(raw.sysctl) : {}
  const vm = raw.vmStat ? parseVmStat(raw.vmStat) : null
  const disk = raw.df ? parseDf(raw.df) : null
  const swap = parseSwap(ctl['vm.swapusage'])
  const totalBytes = toInt(ctl['hw.memsize'])
  const pagesOf = (...names: string[]) => {
    if (!vm || names.some(n => vm.pages[n] === undefined)) return null
    return names.reduce((sum, n) => sum + vm.pages[n]!, 0) * vm.pageSize
  }
  const usedBytes = pagesOf('active', 'wired down', 'occupied by compressor')
  const usedPercent =
    usedBytes !== null && totalBytes ? Math.min(100, Math.max(0, (usedBytes / totalBytes) * 100)) : null
  return {
    at,
    totalBytes,
    cores: toInt(ctl['hw.ncpu']),
    usedBytes,
    freeBytes: pagesOf('free', 'speculative'),
    compressedBytes: pagesOf('occupied by compressor'),
    usedPercent,
    pressure: pressureOf(toInt(ctl['kern.memorystatus_level']), vm, totalBytes),
    swapUsedBytes: swap?.usedBytes ?? null,
    swapTotalBytes: swap?.totalBytes ?? null,
    load1: parseLoad(ctl['vm.loadavg']),
    diskFreeBytes: disk?.freeBytes ?? null,
    diskTotalBytes: disk?.totalBytes ?? null,
  }
}

/** One process: its executable's basename and the app it rolls up under. */
export type Proc = { pid: number; ppid: number; rssKB: number; name: string; app: string }

/**
 * The app a process belongs to: the outermost `<Name>.app` in its executable
 * path (so "Google Chrome Helper (Renderer)" rolls up under "Google Chrome"),
 * else the basename. macOS `ps -o comm=` prints the full path.
 */
export function appOf(path: string): string {
  const bundle = /(?:^|\/)([^/]+)\.app(?:\/|$)/.exec(path)
  return bundle ? bundle[1]! : basename(path)
}

/**
 * Text another process wrote (a heartbeat's label or model, a ps app name),
 * squashed to one printable line before it is drawn or written into the /mem
 * row the model reads: C0/C1 controls (ESC, newlines) and line separators
 * become spaces; format characters (bidi overrides, zero-width, Unicode tags)
 * are dropped; runs of whitespace collapse; the result is cut to `max` code
 * points. Without this a crafted label could forge extra lines (a fake
 * "Optimize:" section) in the table the model reads.
 */
export const oneLine = (text: string, max: number): string =>
  [
    ...text
      .replace(/[\p{Cc}\p{Zl}\p{Zp}]/gu, ' ')
      .replace(/[\p{Cf}\p{Cs}\p{Co}]/gu, '')
      .replace(/\s+/g, ' ')
      .trim(),
  ]
    .slice(0, max)
    .join('')
    .trim()

export const basename = (path: string): string => {
  const trimmed = path.replace(/\/+$/, '')
  return trimmed.slice(trimmed.lastIndexOf('/') + 1) || trimmed
}

/** `ps -axo pid=,ppid=,rss=,comm=` rows (comm last, so it may hold spaces). */
export function parsePs(stdout: string): Proc[] {
  const out: Proc[] = []
  for (const line of stdout.split('\n')) {
    const m = /^\s*(\d+)\s+(\d+)\s+(\d+)\s+(.+?)\s*$/.exec(line)
    if (!m) continue
    const path = m[4]!
    out.push({ pid: Number(m[1]), ppid: Number(m[2]), rssKB: Number(m[3]), name: oneLine(basename(path), 256), app: oneLine(appOf(path), 120) || '?' })
  }
  return out
}

/** Executable names a Claude Code engine runs under (native build, Homebrew's .exe, node or bun). */
export const isEngineName = (name: string): boolean => /^(claude|claude\.exe|node|bun)$/.test(name)

/** `root` and every descendant, by walking ppid links; cycles and a missing root are safe. */
export function descendants(procs: readonly Proc[], root: number): Set<number> {
  const children = new Map<number, number[]>()
  for (const p of procs) {
    if (p.pid === p.ppid) continue
    const list = children.get(p.ppid)
    if (list) list.push(p.pid)
    else children.set(p.ppid, [p.pid])
  }
  const seen = new Set<number>()
  if (!procs.some(p => p.pid === root)) return seen
  const queue = [root]
  while (queue.length > 0) {
    const pid = queue.pop()!
    if (seen.has(pid)) continue
    seen.add(pid)
    for (const child of children.get(pid) ?? []) queue.push(child)
  }
  return seen
}

/**
 * RSS of a process tree in MB: the engine plus its MCP servers, shells and test
 * engines. In-process agents are inside the engine's own RSS. Null when the
 * root is not in the table. Approximate: RSS undercounts compressed pages.
 */
export function treeMB(procs: readonly Proc[], root: number): number | null {
  const tree = descendants(procs, root)
  if (tree.size === 0) return null
  let kb = 0
  for (const p of procs) if (tree.has(p.pid)) kb += p.rssKB
  return Math.round(kb / 1024)
}

/** Claude Code engines that run without mem-gauge, summed so their memory is not hidden or blamed on an app. */
export type Unregistered = { count: number; rssMB: number }
/** The unregistered engines one by one (their process trees' memory), with the totals. */
export type UnregisteredRoots = Unregistered & { roots: { pid: number; rssMB: number }[] }

const isClaudeEngine = (name: string) => name === 'claude' || name === 'claude.exe'

/**
 * Finds Claude Code engines outside `covered` (the registered sessions' trees),
 * counts each outermost one with its descendants (a nested `claude -p` or test
 * engine counts inside its parent), and adds every pid it counted to `covered`.
 */
export function claimUnregistered(procs: readonly Proc[], covered: Set<number>): UnregisteredRoots {
  const byPid = new Map(procs.map(p => [p.pid, p]))
  const engines = procs.filter(p => isClaudeEngine(p.name) && !covered.has(p.pid))
  const enginePids = new Set(engines.map(p => p.pid))
  const isRoot = (p: Proc) => {
    let parent = byPid.get(p.ppid)
    for (let hops = 0; parent && hops < 64; hops += 1) {
      if (enginePids.has(parent.pid) || covered.has(parent.pid)) return false
      if (parent.pid === parent.ppid) break
      parent = byPid.get(parent.ppid)
    }
    return true
  }
  let count = 0
  let kb = 0
  const roots: { pid: number; rssMB: number }[] = []
  for (const root of engines.filter(isRoot)) {
    count += 1
    let rootKB = 0
    for (const pid of descendants(procs, root.pid)) {
      if (covered.has(pid)) continue
      covered.add(pid)
      rootKB += byPid.get(pid)?.rssKB ?? 0
    }
    kb += rootKB
    roots.push({ pid: root.pid, rssMB: rootKB / 1024 })
  }
  return { count, rssMB: Math.round(kb / 1024), roots }
}

/** The top `n` apps by RSS, leaving out every pid in `exclude` (the Claude session trees). */
export function topApps(procs: readonly Proc[], exclude: ReadonlySet<number>, n = 8): AppUsage[] {
  const byApp = new Map<string, { kb: number; count: number }>()
  for (const p of procs) {
    if (exclude.has(p.pid) || p.rssKB <= 0) continue
    const row = byApp.get(p.app) ?? { kb: 0, count: 0 }
    row.kb += p.rssKB
    row.count += 1
    byApp.set(p.app, row)
  }
  return [...byApp.entries()]
    .map(([name, row]) => ({ name, rssMB: Math.round(row.kb / 1024), processes: row.count }))
    .sort((a, b) => b.rssMB - a.rssMB || a.name.localeCompare(b.name))
    .slice(0, n)
}

/** The registry file one session's copy writes; no prompt text, no secrets. */
export type RegistryEntry = {
  v: 1
  sessionId: string
  pid: number | null
  label: string
  cwd: string
  model: string
  rssMB: number | null
  contextPercent: number | null
  contextTokens: number | null
  contextWindow: number | null
  rateLimitPercent: number | null
  agents: number
  lastActivityAt: number
  startedAt: number
  updatedAt: number
}

const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)
const numOrNull = (v: unknown): number | null => (isNum(v) ? v : null)
const str = (v: unknown, max: number): string => (typeof v === 'string' ? v.slice(0, max) : '')
/** A field drawn or reported as text: one printable line (see oneLine). */
const line = (v: unknown, max: number): string => (typeof v === 'string' ? oneLine(v.slice(0, max * 4), max) : '')

/** Session ids become file names, so only a plain id shape is accepted. */
export const isSessionId = (id: string): boolean => /^[A-Za-z0-9_-]{1,128}$/.test(id)

/**
 * A registry file's text, validated field by field. Writes are not atomic, so a
 * half-written or foreign file is null (left out of the table until a later tick
 * reads it whole, or collected), never a thrown tick. Another session wrote
 * it, so every drawn text field is squashed to one printable line.
 */
export function parseEntry(text: string): RegistryEntry | null {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return null
  }
  if (!raw || typeof raw !== 'object') return null
  const o = raw as Record<string, unknown>
  const sessionId = str(o['sessionId'], 128)
  if (!isSessionId(sessionId) || !isNum(o['updatedAt'])) return null
  const pid = numOrNull(o['pid'])
  return {
    v: 1,
    sessionId,
    pid: pid !== null && Number.isSafeInteger(pid) && pid > 1 ? pid : null,
    label: line(o['label'], 120) || sessionId.slice(0, 8),
    cwd: str(o['cwd'], 1024),
    model: line(o['model'], 80),
    rssMB: numOrNull(o['rssMB']),
    contextPercent: numOrNull(o['contextPercent']),
    // An entry an older build wrote has neither; null makes the tip fall back to the percent.
    contextTokens: numOrNull(o['contextTokens']),
    contextWindow: numOrNull(o['contextWindow']),
    rateLimitPercent: numOrNull(o['rateLimitPercent']),
    agents: isNum(o['agents']) ? Math.max(0, Math.round(o['agents'])) : 0,
    lastActivityAt: isNum(o['lastActivityAt']) ? o['lastActivityAt'] : 0,
    startedAt: isNum(o['startedAt']) ? o['startedAt'] : 0,
    updatedAt: o['updatedAt'],
  }
}

/**
 * live, stale or gone. Gone needs proof: the ps table was taken after the
 * session started and its pid is missing, or now belongs to something that is
 * not an engine (pid reuse). Without a ps table or a pid, age alone decides.
 */
export function statusOf(
  entry: RegistryEntry,
  now: number,
  procs: { at: number; byPid: ReadonlyMap<number, Proc> } | null,
): SessionStatus {
  if (entry.pid !== null && procs && procs.at > entry.startedAt) {
    const proc = procs.byPid.get(entry.pid)
    if (!proc || !isEngineName(proc.name)) return 'gone'
  }
  return now - entry.updatedAt > STALE_MS ? 'stale' : 'live'
}

/** Whether a registry file should be removed by this tick's garbage collection. */
export function isCollectable(entry: RegistryEntry | null, status: SessionStatus | null, now: number, mtimeMs: number): boolean {
  if (entry === null) return now - mtimeMs > GC_MS
  if (now - entry.updatedAt > MAX_AGE_MS) return true
  return status === 'gone' && now - entry.updatedAt > GC_MS
}

/** A registry entry as a drawable row. */
export function rowOf(entry: RegistryEntry, status: SessionStatus, now: number, thisId: string): SessionRow {
  return {
    sessionId: entry.sessionId,
    label: entry.label,
    model: entry.model,
    rssMB: entry.rssMB,
    contextPercent: entry.contextPercent,
    contextTokens: entry.contextTokens,
    contextWindow: entry.contextWindow,
    rateLimitPercent: entry.rateLimitPercent,
    agents: entry.agents,
    idleMinutes: entry.lastActivityAt > 0 ? Math.max(0, Math.floor((now - entry.lastActivityAt) / 60_000)) : null,
    status,
    isThis: entry.sessionId === thisId,
    hasMod: true,
  }
}

/** What the engine's own session record (~/.claude/sessions/<pid>.json) says that the pane can use. */
export type EngineSession = { sessionId: string; label: string; idleMinutes: number | null }

/**
 * The engine's record of a running session, written by the CLI itself for
 * every session (mod or not): its id, its name (or the folder it runs in)
 * and when it last changed. Null for a torn or foreign file, or one that is
 * not about `pid`. Every text is cleaned to one line.
 */
export function decodeEngineSession(text: string, pid: number, now: number): EngineSession | null {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return null
  }
  if (!raw || typeof raw !== 'object') return null
  const o = raw as Record<string, unknown>
  if (o['pid'] !== pid) return null
  const id = typeof o['sessionId'] === 'string' && isSessionId(o['sessionId']) ? o['sessionId'] : `engine-${pid}`
  const name = typeof o['name'] === 'string' ? oneLine(o['name'].slice(0, 1024), 100) : ''
  const cwd = typeof o['cwd'] === 'string' ? oneLine(basename(o['cwd'].slice(0, 4096)), 100) : ''
  const updatedAt = isNum(o['updatedAt']) ? o['updatedAt'] : null
  return {
    sessionId: id,
    label: name || cwd || `claude (pid ${pid})`,
    idleMinutes: updatedAt === null ? null : Math.max(0, Math.floor((now - updatedAt) / 60_000)),
  }
}

/** A row for a session that does not run mem-gauge, from the engine's record and its process tree. */
export function engineRow(pid: number, rssMB: number, session: EngineSession): SessionRow {
  return {
    sessionId: session.sessionId,
    label: session.label,
    model: '',
    rssMB,
    contextPercent: null,
    contextTokens: null,
    contextWindow: null,
    rateLimitPercent: null,
    agents: 0,
    idleMinutes: session.idleMinutes,
    status: 'live',
    isThis: false,
    hasMod: false,
  }
}

/** Live first by RSS (largest first), then stale, then gone. */
export function sortRows(rows: readonly SessionRow[]): SessionRow[] {
  const rank: Record<SessionStatus, number> = { live: 0, stale: 1, gone: 2 }
  return [...rows].sort((a, b) => rank[a.status] - rank[b.status] || (b.rssMB ?? -1) - (a.rssMB ?? -1))
}

/** The used-memory quintile as a ring glyph: ○ ◔ ◑ ◕ ●. */
export function glyph(usedPercent: number | null): string {
  if (usedPercent === null || !Number.isFinite(usedPercent)) return '?'
  const rings = ['○', '◔', '◑', '◕', '●']
  return rings[Math.min(4, Math.max(0, Math.floor(usedPercent / 20)))]!
}

/** "1.8 GB" from 1.0 GB up, "512 MB" below. */
export function formatMB(mb: number | null): string {
  if (mb === null || !Number.isFinite(mb)) return '?'
  return mb >= 1024 ? `${(mb / 1024).toFixed(1)} GB` : `${Math.round(mb)} MB`
}

/** "572", "12.3k", "184k" (whole k from 100k), "1.2M": a token count short enough for a tip's text. */
export function formatTokens(n: number | null): string {
  if (n === null || !Number.isFinite(n) || n < 0) return '?'
  const tenth = (v: number) => String(Math.round(v * 10) / 10)
  if (Math.round(n) < 1000) return String(Math.round(n))
  if (Math.round(n / 1000) >= 1000) return `${tenth(n / 1_000_000)}M`
  return n < 100_000 && Math.round((n / 1000) * 10) / 10 < 100 ? `${tenth(n / 1000)}k` : `${Math.round(n / 1000)}k`
}

export const formatBytes = (bytes: number | null): string => formatMB(bytes === null ? null : bytes / MB)

const isAlarm = (p: Pressure) => p === 'warn' || p === 'critical'

/** "✓" when memory pressure is fine, "! warn" / "! critical" under pressure, "?" when unread. */
export function pressureText(p: Pressure): string {
  return p === 'ok' ? '✓' : p === 'unknown' ? '?' : `! ${p}`
}

/**
 * The gauge row's text in two parts: `main` ('Memory 60% · Pressure ✓ · 7 sessions',
 * "! " in front under pressure, '! Wrap requested (2.0 GB)' first when asked) and
 * `disk` ('41 GB free'), which the desktop draws behind a disk icon.
 */
export function summaryParts(snapshot: Snapshot, wrap: WrapRequest | null): { main: string; disk: string } {
  const m = snapshot.machine
  const live = snapshot.sessions.filter(s => s.status === 'live').length
  const parts = [
    `${isAlarm(m.pressure) ? '! ' : ''}Memory ${m.usedPercent === null ? '--' : `${Math.round(m.usedPercent)}%`}`,
    `Pressure ${pressureText(m.pressure)}`,
    `${live} session${live === 1 ? '' : 's'}`,
  ]
  if (wrap) parts.unshift(`! Wrap requested (${wrap.freesMB === null ? '?' : formatMB(wrap.freesMB)})`)
  return { main: parts.join(' · '), disk: `${formatBytes(m.diskFreeBytes)} free` }
}

/** The one-line form (terminal row and the optional status line): 'Memory 60% · Pressure ✓ · 7 sessions · Disk 41 GB free'. */
export function statusLine(snapshot: Snapshot, wrap: WrapRequest | null): string {
  const { main, disk } = summaryParts(snapshot, wrap)
  return `${main} · Disk ${disk}`
}

/** "901 GB" from 10 GB up, "9.5 GB" below, "512 MB" under 1 GB; "--" unread. The footer is narrow. */
export function formatCompact(bytes: number | null): string {
  if (bytes === null || !Number.isFinite(bytes)) return '--'
  const gb = bytes / (1024 * MB)
  if (gb >= 10) return `${Math.round(gb)} GB`
  if (gb >= 1) return `${gb.toFixed(1)} GB`
  return `${Math.round(bytes / MB)} MB`
}

/**
 * The desktop footer row, kept short because the mode strip clips what does
 * not fit: the used percent, the free disk space, and whether something needs
 * attention (pressure, or a wrap request). Pressure itself is read in the pane.
 */
export function footerParts(snapshot: Snapshot, wrap: WrapRequest | null): { used: string; disk: string; diskPct: string; alarm: boolean } {
  const m = snapshot.machine
  const full = m.diskTotalBytes !== null && m.diskFreeBytes !== null && m.diskTotalBytes > 0
    ? `${Math.round((100 * (m.diskTotalBytes - m.diskFreeBytes)) / m.diskTotalBytes)}%`
    : '--'
  return {
    used: m.usedPercent === null ? '--' : `${Math.round(m.usedPercent)}%`,
    disk: formatCompact(m.diskFreeBytes),
    // The disk's fullness, for the one-chip footer: the same reading as the memory percent.
    diskPct: full,
    alarm: isAlarm(m.pressure) || wrap !== null,
  }
}

/** A monochrome disk-drive icon (no script, no external refs) for the gauge row. */
export function diskSvg(size = 14): string {
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" width="${size}" height="${size}" role="img" aria-label="Disk">` +
    `<rect x="1.5" y="4" width="13" height="8" rx="2" fill="none" stroke="${RING_TRACK}" stroke-width="1.5"/>` +
    `<circle cx="11.5" cy="8" r="1.1" fill="${RING_TRACK}"/><line x1="4" y1="8" x2="8.5" y2="8" stroke="${RING_TRACK}" stroke-width="1.5" stroke-linecap="round"/></svg>`
  )
}

/** A text gauge for surfaces with no Svg: "███████░░░░░ 62%". */
export function bar(usedPercent: number | null, width: number): string {
  const cells = Math.max(4, Math.min(40, Math.floor(width)))
  if (usedPercent === null) return `${'░'.repeat(cells)} --`
  const filled = Math.round((Math.min(100, Math.max(0, usedPercent)) / 100) * cells)
  return `${'█'.repeat(filled)}${'░'.repeat(cells - filled)} ${Math.round(usedPercent)}%`
}

/** Apple system red: the arc that fills with used memory, the same on light and dark. */
const RING_RED = '#FF3B30'
const RING_TRACK = '#8E8E93'

/**
 * A gauge icon: a muted track, a red arc that fills clockwise from twelve with
 * used percent, and the percent centered inside, as an SVG document (no
 * script, no external refs). `size` is the drawn box in CSS pixels; the type
 * scales up for the small icon under the prompt so "60%" stays legible.
 */
export function ringSvg(usedPercent: number | null, pressure: Pressure, size = 88, withLabel = true, title?: string): string {
  const pct = usedPercent === null ? 0 : Math.min(100, Math.max(0, usedPercent))
  const r = 15.915 // circumference 100, so the dash array is the percent
  const label = usedPercent === null ? '--' : `${Math.round(usedPercent)}%`
  const small = size <= 40
  const stroke = small ? 4.2 : 3.4
  const font = small ? (label.length > 3 ? 9.5 : 10.5) : 8
  const y = small ? 21.7 : 20.8
  const label2 = title ?? `Memory ${label} used, pressure ${pressure}`
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 36 36" width="${size}" height="${size}" role="img" aria-label="${label2}">` +
    `<circle cx="18" cy="18" r="${r}" fill="none" stroke="${RING_TRACK}" stroke-opacity="0.28" stroke-width="${stroke}"/>` +
    `<circle cx="18" cy="18" r="${r}" fill="none" stroke="${RING_RED}" stroke-width="${stroke}" ` +
    `stroke-linecap="round" stroke-dasharray="${pct.toFixed(1)} ${(100 - pct).toFixed(1)}" transform="rotate(-90 18 18)"/>` +
    (withLabel
      ? `<text x="18" y="${y}" text-anchor="middle" font-family="-apple-system, system-ui, sans-serif" ` +
        `font-size="${font}" font-weight="700" fill="${RING_TRACK}">${label}</text>`
      : '') +
    '</svg>'
  )
}

/** Pads or cuts `text` to exactly `width` columns (with an ellipsis when cut). */
export function fit(text: string, width: number, align: 'left' | 'right' = 'left'): string {
  if (width <= 0) return ''
  const chars = [...text]
  if (chars.length > width) return width === 1 ? '…' : `${chars.slice(0, width - 1).join('')}…`
  const pad = ' '.repeat(width - chars.length)
  return align === 'left' ? text + pad : pad + text
}

/** machine.json: one collector's reading, shared so N sessions do not each run vm_stat, df and ps. */
export type MachineFile = { v: 1; at: number; stats: MachineStats; procs: Proc[] | null }

type ProcTuple = [number, number, number, string, string]

export function encodeMachine(file: MachineFile): string {
  const procs = file.procs?.map((p): ProcTuple => [p.pid, p.ppid, p.rssKB, p.name, p.app]) ?? null
  return JSON.stringify({ v: 1, at: file.at, stats: file.stats, procs })
}

const PRESSURES: readonly Pressure[] = ['ok', 'warn', 'critical', 'unknown']

/** machine.json back, every field checked; null for a half-written or foreign file. */
export function decodeMachine(text: string): MachineFile | null {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return null
  }
  if (!raw || typeof raw !== 'object') return null
  const o = raw as Record<string, unknown>
  const s = o['stats'] as Record<string, unknown> | null
  if (o['v'] !== 1 || !isNum(o['at']) || !s || typeof s !== 'object') return null
  const pressure = PRESSURES.includes(s['pressure'] as Pressure) ? (s['pressure'] as Pressure) : 'unknown'
  const stats: MachineStats = {
    at: o['at'],
    totalBytes: numOrNull(s['totalBytes']),
    cores: numOrNull(s['cores']),
    usedBytes: numOrNull(s['usedBytes']),
    freeBytes: numOrNull(s['freeBytes']),
    compressedBytes: numOrNull(s['compressedBytes']),
    usedPercent: numOrNull(s['usedPercent']),
    pressure,
    swapUsedBytes: numOrNull(s['swapUsedBytes']),
    swapTotalBytes: numOrNull(s['swapTotalBytes']),
    load1: numOrNull(s['load1']),
    diskFreeBytes: numOrNull(s['diskFreeBytes']),
    diskTotalBytes: numOrNull(s['diskTotalBytes']),
  }
  let procs: Proc[] | null = null
  if (Array.isArray(o['procs'])) {
    procs = []
    for (const t of o['procs'] as unknown[]) {
      if (!Array.isArray(t) || t.length !== 5) return null
      const [pid, ppid, rssKB, name, app] = t as unknown[]
      if (!isNum(pid) || !isNum(ppid) || !isNum(rssKB) || typeof name !== 'string' || typeof app !== 'string') return null
      // Another session wrote this file: names are cleaned as if ps had just printed them.
      procs.push({ pid, ppid, rssKB, name: oneLine(name.slice(0, 1024), 256), app: oneLine(app.slice(0, 1024), 120) })
    }
  }
  return { v: 1, at: o['at'], stats, procs }
}

/** A wrap request file another session wrote for this one. */
export function decodeWrapRequest(text: string): WrapRequest | null {
  try {
    const o = JSON.parse(text) as Record<string, unknown>
    if (!o || typeof o !== 'object' || !isNum(o['at'])) return null
    // Another session wrote this file: a figure out of range is dropped, not drawn.
    const frees = numOrNull(o['freesMB'])
    return { at: o['at'], freesMB: frees !== null && frees >= 0 && frees < 16 * 1024 * 1024 ? frees : null }
  } catch {
    return null
  }
}

/** The model id without the vendor prefix, for narrow columns: "fable-5-1". */
export const shortModel = (model: string): string => model.replace(/^claude-/, '') || '?'

/** A git branch name safe to draw: printable, one line, bounded. */
export const cleanBranch = (text: string): string | null => {
  const line = text.trim().split('\n')[0] ?? ''
  return /^[\x21-\x7e]{1,100}$/.test(line) ? line : null
}

